T["   %s  %d Spawns, %s pro Kill%s"] = "   %s  %d spawns, %s per kill%s"
T["   %s: %s, %s XP, Level %d bis %d"] = "   %s: %s, %s XP, level %d to %d"
T["   %s: ca %d Ruf pro Kill (%d gelernt)%s%s"] = "   %s: about %d rep per kill (%d learned)%s%s"
T["   (Quests, Beute, Verkauf, Flüge, Reparatur, Lehrer, Einkäufe) mit Saldo."] = "   (quests, loot, sales, flights, repairs, trainers, purchases) with balance."
T["   AH Preise kommen von dem Addon, das du hast: "] = "   AH prices come from the addon you have: "
T["   Als Geist zeigt er zur Leiche."] = "   As a ghost it points to your corpse."
T["   Angeln: Open World führt zu einer Stelle, die Forever Wegweiser kennt, sonst ins Gebiet mit dem Hinweis, eine Stelle am Wasser zu suchen. Schwärme brauchen GatherMate2."] = "   Fishing: Open World leads to a spot Forever Wegweiser knows, otherwise into the zone with a hint to find a spot by the water. Fish schools need GatherMate2."
T["   Bei allen drei: Pfeil, Abgaben, Folgequests, Klassenquests, Questlog bis 40 und Entdecken auf dem Weg."] = "   All three have: arrow, turn ins, follow-up quests, class quests, quest log up to 40 and exploring on the way."
T["   Berge rot (dort geht der Weg nicht durch), rechte malt Wege blau (dort lieber lang), Shift und rechte Maustaste löscht,"] = "   mountains red (the way never goes through), the right button paints paths blue (preferred), Shift and right button erases,"
T["   Bis Level %d noch ca %s"] = "   To level %d: about %s left"
T["   Das Symbol links vom Pfeil anklicken visiert den NPC oder Mob an, nur mit genau dem Namen, so wie das Spiel ihn zeigt. Zeigt der Pfeil auf einen Händler, Lehrer oder Wirt, ist es dieser."] = "   Clicking the icon left of the arrow targets the NPC or mob, only by its exact name as the game shows it. If the arrow points to a vendor, trainer or innkeeper, it targets that one."
T["   Das grosse Fenster hat nur Start, Meine Route, Mein Weg, Einstellungen (als Ja und Nein Fragen) und Hilfe."] = "   The main window only has Start, My Route, My Path, Settings (as yes and no questions) and Help."
T["   Dazwischen gibt es je zwei Zwischenstufen. Ist Grinden aus, sind die zwei schnellsten Stufen gesperrt."] = "   In between there are two more steps each. If grinding is off, the two fastest steps are locked."
T["   Der Pfeil folgt dem Plan. Neu gerechnet wird nur ein Abschnitt, wenn du zu weit weg bist, der ganze Plan bei Neu rechnen, neuen Einstellungen oder alle 5 Level zur Prüfung."] = "   The arrow follows the plan. Only one section is recalculated if you're too far away, the whole plan on Recalculate, new settings or every 5 levels as a check."
T["   Der Wert pro Kill wird aus deiner Beute gelernt: Geld, Items und Kürschnern. Noch unbekannte Mobs: Geld nach Level plus"] = "   The value per kill is learned from your loot: money, items and skinning. Mobs not known yet: money by level plus"
T["   Dungeons, in denen du alle Quests erledigt hast, stehen grün ganz unten in der Liste."] = "   Dungeons where you've done all quests are shown in green at the very bottom of the list."
T["   Erkunden %d Gebiete: ca %d XP, %s"] = "   Explore %d areas: about %d XP, %s"
T["   Erster Haken: eingesammelt. Zweiter Haken: kommt in die eigene Bücher Route.  "] = "   First check: collected. Second check: goes into your own book route.  "
T["   Farbe vorne: grün gelernt, gelb teils, orange noch geschätzt. Rechts siehst du Mobs, beste Drops und die Anreise."] = "   Color in front: green learned, yellow partly, orange still estimated. On the right you see mobs, best drops and how to get there."
T["   Fertige Fraktionen (Ehrfürchtig oder alle Quests erledigt) stehen grün ganz unten."] = "   Finished factions (Exalted or all quests done) are shown in green at the very bottom."
T["   Flugpunkte, Entdecken) und Zeit (Stunden Budget, Feierabend, Questlog aufräumen). Maus drauf erklärt jeden Knopf."] = "   Flight points, Explore) and Time (Time budget, Call it a day, Clean up quest log). Hover explains each button."
T["   Fraktionen mit Ruf für Mobs (z.B. Holzschlundfeste, Argentumdämmerung, Rabenholdt) stehen mit "] = "   Factions with reputation from mobs (e.g. Timbermaw Hold, Argent Dawn, Ravenholdt) are marked "
T["   Gebiete anhaken: die Route bleibt nur dort. Nichts angehakt: Forever Wegweiser sucht die besten Gebiete selber."] = "   Check zones: the route stays only there. Nothing checked: Forever Wegweiser finds the best zones itself."
T["   Geplant: %s, %s"] = "   Planned: %s, %s"
T["   Geplant: %s, laut Plan noch %s"] = "   Planned: %s, plan says %s left"
T["   Geplant: %s, |cffff5050schon %s drüber|r"] = "   Planned: %s, |cffff5050already %s over|r"
T["   Gesperrte Karten zeigen, ab welchem Level sie kommen."] = "   Locked cards show the level they unlock at."
T["   Gewertet wird nach den Werten für deine Klasse, Rüstungstyp und Waffen, die du tragen kannst."] = "   Rated by the stats for your class, armor type and the weapons you can use."
T["   Gold pro Stunde = Kills pro Stunde mal Wert pro Kill. Kills kommen aus deiner Zeit pro Kill, dem Laufweg und den Respawns."] = "   Gold per hour = kills per hour times value per kill. Kills come from your time per kill, the walking distance and the respawns."
T["   Grind %s (Mobs %d-%d) bis Level %d: ca %d XP, %s"] = "   Grind %s (mobs %d-%d) to level %d: about %d XP, %s"
T["   Grösse unter Einstellungen: "] = "   Size under Settings: "
T["   Grösse vom Pfeil: Einstellungen, Route und Karte, mit dem Schieberegler (50 bis 300 Prozent). Nur der Pfeil wird grösser, der Text bleibt gleich. Bei vielen Fundorten zeigt er auf die Mitte vom Gebiet und bleibt dort, bis du in einem anderen Gebiet bist."] = "   Arrow size: Settings, Route and Map, with the slider (50 to 300 percent). Only the arrow gets bigger, the text stays the same. With many spawn spots it points to the middle of the area and stays there until you're in another area."
T["   Haken weg nimmt eine Quest raus.  "] = "   Unchecking removes a quest.  "
T["   Händler und Feierabend Knopf im HUD, Gruppen Sync, Quests automatisch teilen, Elite Quests (in der Gruppe an, solo aus),"] = "   Vendor and Call it a day button in the HUD, group sync, share quests automatically, elite quests (on in a group, off solo),"
T["   Händler, Feierabend, Einkaufsliste, Neu rechnen und das grosse Fenster. Im Menü steht nur, was schon frei ist."] = "   Vendor, Call it a day, Shopping list, Recalculate and the main window. The menu only shows what's already unlocked."
T["   Ist ein Abschnitt fertig, rechnet sie den nächsten von selbst, immer weiter bis Level 60. Stirbst du weit weg, rechnet sie ab dort neu."] = "   When a section is done, it calculates the next one by itself, all the way to level 60. If you die far away, it recalculates from there."
T["   Items, die es auch ohne Quest gibt (z.B. Wolfsfleisch), plant die Route schon vor dem Annehmen ein, wenn die Mobs auf dem Weg liegen."] = "   Items you can also get without the quest (e.g. wolf meat) are planned in before you accept it, if the mobs are on the way."
T["   Kampf %d%%, Laufen %d%%, Fliegen %d%%, Tot %d%%, Stillstand %d%%"] = "   Combat %d%%, Walking %d%%, Flying %d%%, Dead %d%%, Idle %d%%"
T["   Kills %d, Quests %d, Tode %d, Entdeckt %d, Flüge %d, Reparaturen %d"] = "   Kills %d, Quests %d, Deaths %d, Discovered %d, Flights %d, Repairs %d"
T["   Kommt eine neue Funktion dazu, steht im Mini Fenster "] = "   When a new feature is added, the mini window shows "
T["   Kräuter und Erz kommen aus GatherMate2 oder den eingebauten Gebietslisten. Forever Wegweiser lernt selber dazu: Kräuter, Erz, Angelstellen,"] = "   Herbs and ore come from GatherMate2 or the built-in zone lists. Forever Wegweiser also learns by itself: herbs, ore, fishing spots,"
T["   Level %d bis %d"] = "   Level %d to %d"
T["   Maus drauf erklärt das Symbol, leuchtend heisst an. Das Logo oben klappt die Leiste zu und wieder auf."] = "   Hover explains the icon, glowing means on. The logo at the top collapses and expands the bar."
T["   Mit Laufwegen, Ketten, Level, Ruf, höchstens 40 Quests im Log (Forever) und Klassenquests immer dabei (rosa markiert)."] = "   With walking paths, chains, level, reputation, at most 40 quests in the log (Forever) and class quests always included (marked pink)."
T["   Mit dem Schalter "] = "   With the toggle "
T["   Nochmal machen: Einstellungen, "] = "   Do it again: Settings, "
T["   Oben den Beruf wählen, links die Sachen anhaken. Nur was du mit deinem Skill kannst, ist wählbar, sonst steht, wie viele Punkte fehlen."] = "   Pick the profession at the top, check the things on the left. Only what your skill allows can be picked, otherwise it shows how many points you're missing."
T["   Pro Stunde: %.0f Kills, %.1f Quests"] = "   Per hour: %.0f kills, %.1f quests"
T["   Quests %s (%d): ca %d XP, %s"] = "   Quests %s (%d): about %d XP, %s"
T["   Rechnen (Neu berechnen, Schritt überspringen, Quest auslassen, Export, Laden), Touren (Speed, Alle Quests, Questlog,"] = "   Calculate (Recalculate, Skip step, Skip quest, Export, Load), Tours (Speed, All quests, Quest log,"
T["   Rechts "] = "   On the right "
T["   Rechts an der Karte ist eine schmale Leiste mit Symbolen: Route, Minimap Linie, "] = "   On the right side of the map there's a narrow bar with icons: Route, Minimap line, "
T["   Rechtsklick auf den Forever Wegweiser Text sperrt den Pfeil oder gibt ihn frei. Frei: am Text oder am Pfeil ziehen verschiebt beides."] = "   Right click on the Forever Wegweiser text locks or unlocks the arrow. Unlocked: dragging the text or the arrow moves both."
T["   Reichen die Quests nicht bis zum nächsten Abschnitt, plant er Grind Pausen an guten Spots ein (wenn Grinden an ist). Ohne Grinden nimmt er erst schwächere Quests dazu,"] = "   If the quests aren't enough to reach the next section, it plans grind breaks at good spots (if grinding is on). Without grinding it first adds weaker quests,"
T["   Rest der Zone: ca %s Laufzeit"] = "   Rest of zone: about %s of travel"
T["   Route und Plan ab 28, Statistik und Details ab 34, alle Einstellungen ab 38. Am Ende fast wie Experte, nur ohne Berge malen und Bücher Umweg."] = "   Route and Plan from 28, Statistics and Details from 34, all settings from 38. In the end almost like Expert, just without Paint mountains and book detour."
T["   Route und Plan ab 28, Statistik und Details ab 34, alle Einstellungen ab 38. Am Ende fast wie Experte, nur ohne Malen und Bücher Umweg."] = "   Route and Plan from 28, Statistics and Details from 34, all settings from 38. In the end almost like Expert, just without painting and book detour."
T["   Saldo: %s%s|r%s"] = "   Balance: %s%s|r%s"
