T["   Stoff, Leder und Co. mit echten Drop Chancen aus der Questie Drop Tabelle."] = "   cloth, leather and so on with real drop chances from the Questie drop table."
T["   Strg für dicken Pinsel. Nochmal klicken oder Karte zu beendet es. Die gemalten Stellen sieht man nur, solange der Knopf an ist."] = "   Ctrl for a thick brush. Click again or close the map to stop. Painted spots only show while the button is on."
T["   Tötest du so einen Mob, lernt Forever Wegweiser Ruf pro Kill, wie viele Kills bis zur nächsten Stufe fehlen und wo es die meisten gibt."] = "   When you kill such a mob, Forever Wegweiser learns reputation per kill, how many kills you need for the next standing and where most of them are."
T["   Unten drei Knöpfe:  "] = "   Three buttons at the bottom:  "
