T["   Viel Laufen: Speed Leveling oder optimierte Route spart Wege."] = "   Lots of running: speed leveling or the optimized route saves travel."
T["   Viel Stillstand: Essen und Trinken beim Laufen planen, Quests vorher lesen."] = "   Lots of standing still: plan food and drink along the way, read quests ahead."
T["   Viele Tode: Mobs eher 1 bis 2 Level unter dir, Elite Gebiete meiden."] = "   Lots of deaths: pick mobs 1 to 2 levels below you, avoid elite areas."
