T["   gesperrte Stellen rot ein, rechte radiert, Shift für dicken Pinsel. Nochmal klicken oder Karte zu beendet es, die roten Stellen"] = "   blocked spots in red, the right button erases, Shift for a thick brush. Click again or close the map to stop, the red spots"
