T["Alles erleben: Elite und Gruppenquests holt die Route später nach, sobald du sie allein schaffst. Oder ihr sucht euch eine Gruppe, dann kommen sie gleich dran."] = "Do everything: the route picks up elite and group quests later, once you can solo them. Or find a group, then they come right away."
