T["Das"] = "This"
T["Forever Wegweiser rechnet dir die schnellste Leveling Route und führt dich mit Pfeil, Karte und Mini HUD."] = "Forever Wegweiser calculates the fastest leveling route for you and guides you with the arrow, map and mini HUD."
T["Du bekommst Bescheid, sobald es soweit ist, mit kurzer Erklärung."] = "You'll get a heads up when it's ready, with a short explanation."
T["Forever Wegweiser sucht jetzt Quests mit besserer Belohnung als deine Ausrüstung. So wirst du unterwegs besser, ohne Händler oder Auktionshaus."] = "Forever Wegweiser now looks for quests with rewards better than your gear. So you upgrade along the way, no vendor or auction house needed."
T["Forever Wegweiser zeigt dir immer, was als Nächstes kommt und wohin du läufst. Du musst nichts planen. Ein paar kurze Fragen, dann geht es los."] = "Forever Wegweiser always shows you what's next and where to go. No planning needed. A few quick questions, then off you go."
T["Das Grabmal"] = "The Sepulcher"
T["Das Mini Fenster sagt dir, was zu tun ist. Ziehen verschiebt es, Rechtsklick sperrt es."] = "The mini window tells you what to do. Drag to move it, right-click to lock it."
T["Das Verlies"] = "The Stockade"
T["Das gilt egal welche Spielweise oder welchen Modus du wählst. Ändern geht später unter Einstellungen."] = "This applies no matter which play style or mode you pick. You can change it later under Settings."
