T["Deine Daten von TaurenRoute wurden übernommen. Der alte Ordner TaurenRoute kann gelöscht werden."] = "Your data from TaurenRoute was carried over. You can delete the old TaurenRoute folder."
T["Deine laufende Route ist gemerkt: "] = "Your current route is saved: "
T["Zeigt den Schritt davor nochmal. Solange du zurück bist, geht die Route nicht von selbst weiter."] = "Shows the previous step again. While you're back there, the route won't move on by itself."
T["Den Text einer exportierten Route hier einfügen (Strg+V) und Laden drücken."] = "Paste the text of an exported route here (Ctrl+V) and press Load."
T["Der Brief droppt in der oberen Schwarzfelsspitze. Ohne ihn lässt dich die Kugel nicht in den Hort."] = "The letter drops in Upper Blackrock Spire. Without it the orb won't let you into the Lair."
T["Der Pfeil führt dich zu allen Questgebern, mit Vorquests, danach zum Eingang."] = "The arrow takes you to all quest givers, prequests included, then to the entrance."
T["Der Pfeil führt um Klippen und Berge herum statt in die Wand."] = "The arrow leads around cliffs and mountains instead of into the wall."
T["Der Pfeil geht zum nächsten Schritt."] = "The arrow moves on to the next step."
T["Der Pfeil in der Mitte zeigt zum nächsten Schritt."] = "The arrow in the middle points to the next step."
T["Der Pfeil steht oben in der Mitte. Ziehen mit der Maus verschiebt ihn."] = "The arrow sits at the top center. Drag it with the mouse to move it."
T["Der Pfeil zeigt jetzt zur Empfehlung. Ignorieren: Knopf im Fenster oder /klg ignorieren"] = "The arrow now points to the suggestion. To ignore: button in the window or /klg ignore"
T["Der Pfeil zeigt zurück. Auslassen mit /klg auslassen oder Quest auslassen unter Meine Route."] = "The arrow points back. Skip it with /klg skip or Skip quest under My Route."
T["Der Plan geht immer bis Level "] = "The plan always goes to level "
T["Der Rest der Reihe geht ab Level %d weiter."] = "The rest of the chain continues at level %d."
T["Der Route folgen. Quests, Wege und Pausen sind geplant."] = "Follow the route. Quests, paths and breaks are planned."
T["Hakt den Schritt ab, der Pfeil zeigt zum nächsten. Meist merkt das Addon das von selbst."] = "Marks the step done, the arrow points to the next. Usually the addon notices by itself."
