T["Ja"] = "Yes"
T["Ja, Gold Quests"] = "Yes, Gold quests"
T["Ja: Bücher, die nah an der Route liegen, kommen mit. Nein: keine Bücher in der Route, du kannst sie später trotzdem gezielt holen."] = "Yes: books close to the route get added. No: no books in the route, you can still go get them later."
T["Ja: Quest Gegenstände funkeln, Kräuter und Erz bekommen ein Symbol. Nein: wie im normalen Spiel."] = "Yes: quest items sparkle, herbs and ore get an icon. No: like the normal game."
T["Ja: Stellen bei Elite Mobs lässt die Route weg."] = "Yes: the route skips spots near elite mobs."
T["Ja: reichen die Quests nicht, plant die Route Grind Pausen ein (bist du voraus, fallen sie weg). Nein: keine Grind Pausen, Sehr zügig und Schnell leveln sind gesperrt, und wo Level fehlen, kommt ein Hinweis: grinden oder Dungeons."] = "Yes: if quests aren't enough, the route plans grind breaks (if you're ahead, they get dropped). No: no grind breaks, Very brisk and Fast leveling are locked, and where levels are missing you get a hint: grind or dungeons."
T["Ja: unter Farmen gibt es die Seiten Berufe und Gold Berufe. Kräuter, Erz, Leder, Stoff, Fleisch und Fische farmen, mit Route."] = "Yes: under Farming you get the Professions and Gold professions pages. Farm herbs, ore, leather, cloth, meat and fish, with a route."
T["Ja: unter Farmen gibt es die Seiten Berufe und Gold Berufe. Kräuter, Erz, Leder, Stoff, Fleisch und Fische farmen, mit Route. Kommt bei Lernen ab Level 10, bei Einsteiger ab 15."] = "Yes: under Farming you get the Professions and Gold professions pages. Farm herbs, ore, leather, cloth, meat and fish, with a route. Unlocks at level 10 in Learning, at 15 in Beginner."
T["Jadefeuer Satyrn"] = "Jadefire Satyrs"
T["Je nach Ruf bei der Argentumdämmerung brauchst du mehr oder weniger Material."] = "Depending on your Argent Dawn reputation you need more or fewer materials."
T["Jede Frage mit Ja oder Nein. Maus auf die Frage erklärt, was passiert."] = "Answer each question with yes or no. Hover a question to see what it does."
T["Jede Karte ist ein Dungeon, Raid oder Schlachtfeld. Unten rechts: wie viele Quests es gibt und wie viele du schon hast. Klick öffnet die Seite mit Quests, Route und Info."] = "Each card is a dungeon, raid or battleground. Bottom right: how many quests there are and how many you have. Click opens the page with quests, route and info."
T["Jede Karte ist ein Ziel. Klick wechselt die Route dahin. Gesperrte Karten zeigen, ab welchem Level sie kommen."] = "Each card is a goal. Click switches the route to it. Locked cards show the level they unlock at."
T["Jede Karte ist eine Stufe. Gelb ist die nächste. Klick auf eine Karte erklärt, was dort neu kommt."] = "Each card is a stage. Yellow is the next one. Click a card to see what's new there."
T["Jede Quest mitnehmen, ohne XP Grenze."] = "Take every quest, no XP limit."
T["Jeder holt einen Teil der Quests, danach teilt ihr sie. Spart viel Laufen."] = "Everyone picks up some of the quests, then you share them. Saves a lot of walking."
T["Jeder in der Gruppe holt einen Teil der Quests, danach teilt ihr sie. Spart viel Laufen."] = "Everyone in the group picks up part of the quests, then you share them. Saves a lot of running."
