T["Nur an, solange der Knopf leuchtet: linke Maustaste malt Stellen, über die der Weg nicht gehen soll, rechte radiert, Shift für dicken Pinsel. Nochmal klicken oder Karte zu beendet es. Die roten Stellen sieht man nur dann."] = "Only on while the button glows: left mouse button paints spots the path should avoid, right erases, Shift for a thick brush. Click again or close the map to stop. The red spots only show then."
T["Nur an, solange der Knopf leuchtet: linke Maustaste malt gute Wege (Strassen, Pässe), rechte radiert, Shift für dicken Pinsel. Dort führt der Weg lieber lang. Grün sieht man nur beim Malen."] = "Only active while the button glows: left mouse button paints good paths (roads, passes), right button erases, Shift for a thick brush. The way prefers these spots. Green only shows while painting."
T["Nur an, solange der Knopf leuchtet: linke Maustaste ziehen malt Berge (rot, dort geht der Weg nicht durch), rechte malt Wege (blau, dort geht der Weg lieber lang), Shift und rechte Maustaste löscht, Strg für dicken Pinsel. Die gemalten Stellen sieht man nur, solange der Knopf an ist."] = "Only active while the button glows: drag with the left mouse button to paint mountains (red, the way never goes through), right button paints paths (blue, the way prefers them), Shift and right button erases, Ctrl for a thick brush. Painted spots only show while the button is on."
T["Nur der Pfeil wird grösser oder kleiner, der Text bleibt gleich."] = "Only the arrow gets bigger or smaller, the text stays the same."
