T["|cff9d9d9dDer Wert pro Kill wird aus deiner Beute gelernt (Geld und Items), Items mit Auktionator Preisen.|r"] = "|cff9d9d9dThe value per kill is learned from your loot (money and items), items at Auctionator prices.|r"
T["|cff9d9d9dDie Prozent sind ungefähr: wie viel besser das Teil nach dieser Wertung ist als dein jetziges. Neu heisst, auf dem Platz hast du noch nichts.|r"] = "|cff9d9d9dThe percent is rough: how much better the item is by this score than your current one. New means you have nothing in that slot yet.|r"
T["|cff9d9d9dDie Route ist fertig, wenn das Ziel erreicht ist.|r"] = "|cff9d9d9dThe route is done once the goal is reached.|r"
T["|cff9d9d9dDiese Fraktion kennst du noch nicht.|r"] = "|cff9d9d9dYou don't know this faction yet.|r"
T["|cff9d9d9dEingesammelt erkennt Forever Wegweiser selbst: am Fundort aufgehoben oder in deinen Taschen. Bücher Route führt zu allen offenen Büchern ausser denen in Dungeons.|r"] = "|cff9d9d9dForever Wegweiser detects collected books by itself: picked up at the spot or in your bags. The books route leads to all open books except those in dungeons.|r"
T["|cff9d9d9dGesucht werden normale Mobs, die du solo schaffst: bis 1 Level über dir und höchstens 8 darunter.|r"] = "|cff9d9d9dIt looks for normal mobs you can solo: up to 1 level above you and at most 8 below.|r"
T["|cff9d9d9dGewertet wird mit den Werten für deine Klasse, Rüstungstyp und Waffen die du tragen kannst.|r"] = "|cff9d9d9dScored with the stat weights for your class, armor type and the weapons you can use.|r"
T["|cff9d9d9dGold wird geschätzt, bis du die Quest einmal beim NPC gesehen hast. Item Belohnungen sind nicht eingerechnet.|r"] = "|cff9d9d9dGold is estimated until you've seen the quest at the NPC once. Item rewards are not included.|r"
T["|cff9d9d9dGold: gelernte Belohnungen sind genau, sonst geschätzt (Belohnung plus Gold statt XP auf 60, plus Beute der Quest Mobs). Item Belohnungen nicht eingerechnet.|r"] = "|cff9d9d9dGold: learned rewards are exact, others estimated (reward plus gold instead of XP at 60, plus loot from quest mobs). Item rewards not included.|r"
T["|cff9d9d9dGrün: jetzt annehmbar. Orange: in ein paar Levels. Rot: Dungeon Quest (Seite Dungeons).|r"] = "|cff9d9d9dGreen: can accept now. Orange: in a few levels. Red: dungeon quest (Dungeons page).|r"
T["|cff9d9d9dJe mehr du farmst, desto genauer: jeder Kill und jede Beute wird pro Mob gelernt.|r"] = "|cff9d9d9dThe more you farm, the more accurate: every kill and every loot is learned per mob.|r"
T["|cff9d9d9dKein AH Addon gefunden, nur Händler Preise. Unterstützt: TSM, Auctionator, Auctioneer, Aux, OribosExchange.|r"] = "|cff9d9d9dNo AH addon found, vendor prices only. Supported: TSM, Auctionator, Auctioneer, Aux, OribosExchange.|r"
T["|cff9d9d9dKeine offenen Quests hierfür, also keine Route nötig.|r"] = "|cff9d9d9dNo open quests for this, so no route needed.|r"
T["|cff9d9d9dKills pro Stunde kommen aus deiner gemessenen Zeit pro Kill, dem Laufweg zwischen den Mobs und den Respawns.|r"] = "|cff9d9d9dKills per hour come from your measured time per kill, the walk between mobs and the respawns.|r"
T["|cff9d9d9dMobs farmen schickt dich zu den Mobs, die dir schon Ruf gegeben haben (am Ort mit den meisten).|r"] = "|cff9d9d9dFarm mobs sends you to the mobs that already gave you rep (to the spot with the most).|r"
