T["Bücher|r, Gold (ab 35, Experte sofort) und OpenMap."] = "Books|r, Gold (from 35, Expert right away) and OpenMap."
T["Wege teilen|r  Wo du gelaufen bist, geht frühestens nach 45 Minuten an andere Spieler mit Forever Wegweiser, ihre Wege kommen zu dir."] = "Share paths|r  Where you walked goes to other players with Forever Wegweiser after 45 minutes at the earliest, their paths come to you."
T["   Erst wenn viele Spieler an verschiedenen Tagen durch eine Stelle laufen, gilt sie als frei. Ein Berg wird nie von anderen gesetzt,"] = "   A spot only counts as free once many players walked through it on different days. Others can never add a mountain,"
T["   er wird höchstens unsicher und erst bei sehr vielen Meldungen frei. Wasser lernt der Pfeil beim Schwimmen, Klippen beim Herunterspringen."] = "   it only gets unsure, and free only after very many reports. The arrow learns water when you swim and cliffs when you jump down."
T["   Nicht gelernt wird im Flug, auf Schiffen und Zeppelinen. "] = "   Nothing is learned while flying or on ships and zeppelins. "
