T["Wege teilen aus: du sendest und empfängst keine Wege mehr."] = "Share paths off: you no longer send or receive paths."
T["Wege teilen an: deine Wege gehen frühestens nach 45 Minuten an andere, ihre kommen zu dir."] = "Share paths on: your paths go to others after 45 minutes at the earliest, theirs come to you."
