T["Das ganze Mini Fenster mit Schrift, Knöpfen, Menü und den Hinweisen darüber wird grösser oder kleiner."] = "The whole mini window with text, buttons, menu and the hints above it gets bigger or smaller."
T["Hinweise als Fenster über dem Mini Fenster?"] = "Hints as a window above the mini window?"
T["Ja: jeder Hinweis als eigene Karte mit X und Gehe zu. Nein: nur der wichtigste im Mini Fenster."] = "Yes: each hint as its own card with X and Go to. No: only the most important one in the mini window."
T["Fenster mit neuen Zaubern alle 2 Level?"] = "Window with new spells every 2 levels?"
T["Bei jedem geraden Level, wenn beim Lehrer etwas wartet: ein Fenster mit Lehrer, Ort und Zaubern."] = "Every even level, if something waits at the trainer: a window with trainer, place and spells."
T["Hinweise|r  Über dem Mini Fenster steht jeder Hinweis und jede Warnung als eigene Karte: X klickt sie weg,"] = "Hints|r  Above the mini window every hint and warning is its own card: X dismisses it,"
T["   Gehe zu schickt dich hin. Händler und Lehrer kommen dabei als Schritt in die Route. Im Menü geht das auch von Hand."] = "   Go to sends you there. Vendors and trainers are added as a route step. The menu can do that by hand too."
T["   Alle 2 Level zeigt ein Fenster die neuen Zauber und den Lehrer. Grösse vom Mini Fenster und Schrift unter dem Pfeil: Einstellungen."] = "   Every 2 levels a window shows the new spells and the trainer. Mini window size and text under the arrow: Settings."
