T["Fahrplan Abschnitt %d live für die Gruppe"] = "Plan section %d live for the group"
T["Du folgst der Gruppen Route von %s, er rechnet für alle."] = "You follow the group route of %s, the leader plans for everyone."
T["Gruppen Route|r  Der Gruppenleiter rechnet für alle, alle anderen sehen genau seine Schritte und springen mit ihm weiter."] = "Group route|r  The group leader plans for everyone, all others see exactly the leader's steps and move on together."
T["   Was du nicht machen kannst (Klassenquest vom Leiter, schon erledigt), steht als 'für Arn, hilf mit' da."] = "   Anything you can't do (the leader's class quest, already done) shows as 'for Arn, help out'."
T["   Lehrer aller Klassen sind Halte für alle, gebunden wird am selben Gasthaus. Meldet sich der Leiter nicht mehr, läuft deine eigene Route."] = "   Trainers of all classes are stops for everyone, everyone binds at the same inn. If the leader goes silent, your own route continues."
T["Neue Zauber bei %s"] = "New spells at %s"
T["Gruppe: %d von %d Quests können alle mitmachen, die kommen bevorzugt"] = "Group: %d of %d quests everyone can do, those come first"
T["   Quests, die alle mitmachen können, nimmt der Leiter bevorzugt. Dafür schickt jeder einmal seine erledigten Quests mit."] = "   Quests everyone can do are preferred by the leader. For that, everyone sends their completed quests once."
T["%s liegt in einer anderen Zone und lohnt sich in dieser Runde kaum, die Route lässt es weg."] = "%s is in another zone and hardly worth it in this round, the route leaves it out."
T["Das Spiel ruckelt beim Rechnen: die Route rechnet jetzt langsamer, dafür flüssiger."] = "The game stutters while calculating: the route now calculates more slowly, but smoothly."
T["Die Route rechnet schon."] = "The route is already being planned."
T["Route wird berechnet, Level %d bis %d. Das Spiel kann dabei kurz ruckeln, das hört von selbst auf."] = "Planning the route, level %d to %d. The game may stutter briefly, it stops on its own."
T["Abschnitt wird neu berechnet ..."] = "Recalculating section ..."
T["Du hast etwas geändert. Route neu berechnen? Das Spiel kann kurz ruckeln. Sonst läuft die alte Route weiter."] = "You changed something. Recalculate the route? The game may stutter briefly. Otherwise the old route keeps going."
T["Die Route ist noch nicht berechnet. Jetzt berechnen? Das Spiel kann dabei kurz ruckeln."] = "The route isn't calculated yet. Calculate now? The game may stutter briefly."
T["Jetzt berechnen"] = "Calculate now"
T["Älterer oder schwacher PC?"] = "Older or weaker PC?"
T["Ja: die Route rechnet langsamer, dafür ruckelt nichts. Bei Ruckeln bremst Forever Wegweiser auch von selbst."] = "Yes: the route calculates more slowly, but nothing stutters. If it stutters, Forever Wegweiser also slows down by itself."
T["Die Route wird erst gerechnet, wenn du auf Berechnen drückst. Erst dann startet sie. Am Anfang kann das Spiel dabei kurz ruckeln, das hört von selbst auf."] = "The route is only planned when you press Plan. Only then does it start. The game may stutter briefly at first, it stops on its own."
