T["Deine Wahl hat sich geändert, die Route ist noch die alte."] = "Your choice changed, the route is still the old one."
T["Noch nicht berechnet."] = "Not calculated yet."
T["Route noch nicht berechnet"] = "Route not calculated yet"
T["Berechnen"] = "Calculate"
T["Klick: jetzt berechnen. Das Spiel kann kurz ruckeln, das hört von selbst auf."] = "Click: calculate now. The game may stutter briefly, that stops by itself."
T["Speichern"] = "Save"
T["Fehler gespeichert, danke! Er landet beim Ausloggen oder /reload im Log."] = "Bug saved, thanks! It goes into the log on logout or /reload."
T["Verbesserung gespeichert, danke! Sie landet beim Ausloggen oder /reload im Log."] = "Suggestion saved, thanks! It goes into the log on logout or /reload."
T["Bitte zuerst etwas eintippen."] = "Please type something first."
T["Fehler melden"] = "Report bug"
T["Verbesserung vorschlagen"] = "Suggest improvement"
T["Was ist passiert, was hast du erwartet? Schritt, Zone und Level kommen von selbst dazu."] = "What happened, what did you expect? Step, zone and level are added automatically."
T["Was sollte besser oder anders sein? Schritt, Zone und Level kommen von selbst dazu."] = "What should be better or different? Step, zone and level are added automatically."
T["Test Notiz"] = "Test note"
T["Verbesserung"] = "Improvement"
T["Test Notiz neben dem Mini Fenster?"] = "Test note next to the mini window?"
T["Kleiner Kasten mit Fehler melden und Verbesserung. Was du eintippst, landet im Test Log."] = "Small box with Report bug and Improvement. What you type goes into the test log."
T["   Weg zu 60 ab 28, Statistik und Details ab 34, alle Einstellungen ab 38. Am Ende fast wie Experte, nur ohne Malen und Bücher Umweg."] = "   Path to 60 from 28, statistics and details from 34, all settings from 38. In the end almost like Expert, just without painting and the book detour."
T["Weg zu 60|r  alle Schritte bis Level 60 zum Anklicken, Zeit pro Level und Zone, mit plus oder minus, wenn fertig."] = "Path to 60|r  all steps up to level 60 to click, time per level and zone, with plus or minus when finished."
T[" Performance 25, Weg zu 60 28, Statistik 34, Gold 35, alle Einstellungen 38 (vorher nur die wichtigsten)"] = " Performance 25, Path to 60 28, statistics 34, gold 35, all settings 38 (before that only the most important)"
T["Weg zu 60"] = "Path to 60"
T["|cff9d9d9dDanach noch %d Schritte bis Level %d. Den ganzen Plan siehst du unter Weg zu 60.|r"] = "|cff9d9d9dThen %d more steps to level %d. The whole plan is under Path to 60.|r"
T["Viel Laufen. Fehlende Flugpunkte holen spart Wege (Meine Route, Planen, Flugpunkte)."] = "Lots of walking. Getting missing flight points saves trips (My Route, Plan, Flight points)."
T["Alle Schritte bis Level 60, Zeit pro Level und Zone"] = "All steps up to level 60, time per level and zone"
T["Alle Schritte vom ganzen Plan bis Level 60 zum Anklicken, mit geplanter Zeit pro Level und Zone und plus oder minus, wenn sie fertig sind."] = "All steps of the whole plan up to level 60 to click, with planned time per level and zone and plus or minus once finished."
T["Im grossen Fenster unter Route, Weg zu 60."] = "In the big window under Route, Path to 60."
T["Alle Schritte bis Level 60"] = "All steps up to level 60"
T["Gewählter Schritt"] = "Selected step"
T["Zum jetzigen Schritt"] = "To current step"
T["Zeit pro Zone"] = "Time per zone"
T["Die Route ist noch nicht berechnet. Unten im Mini Fenster oder unter Meine Route auf Berechnen drücken."] = "The route isn't calculated yet. Press Calculate in the mini window or under My Route."
T["Der Plan bis Level 60 wird gerade berechnet ..."] = "The plan to level 60 is being calculated ..."
T["|cff9d9d9d%s, Level ca %.1f, Abschnitt %d von %d, Schritt %d|r"] = "|cff9d9d9d%s, level about %.1f, section %d of %d, step %d|r"
T["|cff6d6d6dSchon hinter dir. Pfeil hierhin zeigt nochmal dorthin.|r"] = "|cff6d6d6dAlready behind you. Arrow here points there again.|r"
