T["|cff40ff40Du bist ca %.1f Level vor dem Plan.|r"] = "|cff40ff40You are about %.1f levels ahead of the plan.|r"
T["|cffff6060Du bist ca %.1f Level hinter dem Plan.|r"] = "|cffff6060You are about %.1f levels behind the plan.|r"
T["Noch keine Zeiten. Sie kommen, sobald der Plan berechnet ist und du spielst."] = "No times yet. They come once the plan is calculated and you play."
