T["Klassenquest eines Mitspielers, zu lang (Abstecher)"] = "Class quest of a group member, too long (side trip)"
T["|cff9d9d9dWarten: %s macht die Klassenquest %s|r"] = "|cff9d9d9dWait: %s does the class quest %s|r"
T["Warten: %s macht die Klassenquest"] = "Wait: %s does the class quest"
T["Farmen: %d Stück in %d Min, Runde %d (endlos)"] = "Farming: %d items in %d min, round %d (endless)"
T["Runde %d: wieder von vorne, die Stellen sind inzwischen nachgewachsen."] = "Round %d: starting over, the spots have respawned by now."
T[", Runde %d"] = ", round %d"
T["Der neue Look braucht ein Neuladen der Oberfläche. Jetzt neu laden? Die Einrichtung geht danach weiter."] = "The new look needs a UI reload. Reload now? The setup continues afterwards."
T["Nach 60: alle offenen Quests"] = "After 60: all open quests"
T["Los"] = "Go"
T["Route fertig gerechnet, %d Schritte"] = "Route fully calculated, %d steps"
T["nachquesten, alles was noch geht"] = "catch up on every quest still doable"
T["Max Level: alle offenen Quests nachholen?"] = "Max level: do all open quests?"
T["Klick: Route mit allen Quests, die du noch machen kannst (wie Planen, Nach 60). X: ausblenden."] = "Click: route with all quests you can still do (like Plan, After 60). X: hide."
T["Farm Route wird neu gerechnet ..."] = "Recalculating farm route ..."
T["Keine Farmroute gefunden, die bisherige bleibt."] = "No farm route found, the current one stays."
T["Diese Route geht beim aktuellen Schritt weiter, sie hat nichts neu zu rechnen. Für die Leveling Route erst oben Leveling Route wählen."] = "This route continues at the current step, there is nothing to recalculate. For the leveling route, pick Leveling route first."
T["Keine machbare Quest dabei (Dungeon, Level zu tief oder Vorquest fehlt), die bisherige Route bleibt."] = "No doable quest in it (dungeon, level too low or prequest missing), the current route stays."
T["%s ist eine Dungeon Quest, die geht über die Dungeon Seite oder in der Gruppe."] = "%s is a dungeon quest, use the dungeon page or a group for it."
T["Die Vorquests werden trotzdem eingeplant."] = "The prequests are planned anyway."
T["Endlos"] = "Endless"
T["Andere Zone"] = "Other zone"
T["Rechnet die Runde in der nächstbesten Zone. Nach der letzten geht es wieder bei der besten los."] = "Calculates the round in the next best zone. After the last one it starts again with the best."
T["Zeigt die ganze Runde auf der Weltkarte, bevor du startest."] = "Shows the whole round on the world map before you start."
T["Runde im Kreis, bis du aufhörst"] = "Round in a circle until you stop"
T["Eine Runde über %d Stellen, sie läuft im Kreis, bis du aufhörst"] = "One round over %d spots, it loops until you stop"
T["|cff9d9d9dAndere gute Zonen: "] = "|cff9d9d9dOther good zones: "
T["|cff9d9d9dDie Runde läuft im Kreis, bis du im Menü Neu rechnen drückst (zurück zum Leveln).|r"] = "|cff9d9d9dThe round loops until you press Recalculate in the menu (back to leveling).|r"
T["Wegdaten werden vorbereitet, die Route rechnet gleich danach ..."] = "Preparing path data, the route is calculated right after ..."
T["Profil"] = "Profile"
T["Zurück zur Leveling Route, beim Schritt, wo du warst. Nur die nächsten Schritte werden bei Bedarf neu gerechnet."] = "Back to the leveling route, at the step where you were. Only the next steps are recalculated if needed."
T["Deine Berufe Runde. Läuft eine, geht sie weiter, sonst öffnet sich der Planer. Deine Leveling Route bleibt gemerkt."] = "Your profession round. If one is running it continues, otherwise the planner opens. Your leveling route is kept."
T["Deine Gold Route. Läuft eine, geht sie weiter, sonst öffnet sich die Seite Gold Mobs. Deine Leveling Route bleibt gemerkt."] = "Your gold route. If one is running it continues, otherwise the Gold Mobs page opens. Your leveling route is kept."
T["Deine Ruf Route. Läuft eine, geht sie weiter, sonst öffnet sich die Seite Ruf. Deine Leveling Route bleibt gemerkt."] = "Your reputation route. If one is running it continues, otherwise the Reputation page opens. Your leveling route is kept."
T["Profil %s: weiter, wo du warst (Schritt %d von %d)."] = "Profile %s: continuing where you were (step %d of %d)."
T["Profil %s läuft schon."] = "Profile %s is already running."
T["Profil Leveln: die Route wird geladen ..."] = "Profile Leveling: loading the route ..."
T["Profil %s: noch keine Route. Plane im Fenster eine, deine jetzige Route läuft so lange weiter und bleibt gemerkt."] = "Profile %s: no route yet. Plan one in the window, your current route keeps running and is kept."
T["|cff9d9d9d%s, Level ca %.1f, aus einem früheren Plan (vor dem Neu rechnen)|r"] = "|cff9d9d9d%s, level approx %.1f, from an earlier plan (before recalculating)|r"
T["%sLevel fehlt:|r bis Level %.1f grinden oder Dungeons, dann geht die Route weiter"] = "%sLevel missing:|r grind or run dungeons up to level %.1f, then the route continues"
T["noch nicht dort, geplant ca %s"] = "not there yet, planned approx %s"
T["|cffff9030Achtung:|r Für Level %d findet Forever Wegweiser keine Quests (Volk %s, ID %s). Bitte über \"Fehler melden\" kurz Bescheid geben, die Gründe stehen im Log."] = "|cffff9030Note:|r Forever Wegweiser finds no quests for level %d (race %s, ID %s). Please report it via \"Report bug\", the reasons are in the log."
T["Weg zu 60 wird komplett neu berechnet, wie bei einem neuen Charakter."] = "Path to 60 is recalculated completely, like for a new character."
T["Komplett neu berechnen"] = "Recalculate completely"
T["Den ganzen Weg zu 60 komplett neu berechnen? Verlauf und Zeiten werden gelöscht, wie bei einem neuen Charakter."] = "Recalculate the whole path to 60? History and times are deleted, like for a new character."
T["Komplett neu"] = "Completely new"
T["Löscht den Plan, den Verlauf und die Zeiten und rechnet alles neu ab deinem jetzigen Stand, wie bei einem neuen Charakter. Für normale Änderungen reicht Neu rechnen."] = "Deletes the plan, the history and the times and recalculates everything from your current state, like for a new character. For normal changes, Recalculate is enough."
T["tiefe Quest, nur wenn Quests fehlen"] = "low quest, only when quests run short"
T["Quests reichen nicht: %d tiefere Quests kommen dazu, bevor gegrindet wird"] = "Quests aren't enough: %d lower quests are added before grinding"
