T["%sLevel fehlt:|r bis Level %.1f, am besten Dungeon %s, sonst grinden. Dann geht die Route weiter."] = "%sLevel missing:|r up to level %.1f, best run dungeon %s, otherwise grind. Then the route continues."
T["%s oder %s"] = "%s or %s"
T["Dungeon oder grinden"] = "Dungeon or grind"
T["Dungeon"] = "Dungeon"
T["%sGruppe: jetzt passt Dungeon %s|r. Euch fehlen noch ca %.1f Level bis %.1f, dafür ist der Dungeon mit seinen Quests besser als grinden. Die Route gibt es im Fenster unter Dungeons."] = "%sGroup: dungeon %s fits now|r. You still need about %.1f levels to %.1f, the dungeon with its quests beats grinding. The route is in the window under Dungeons."
T["%sGruppe: Dungeon %s|r bis Level %.1f, dann geht die Route weiter."] = "%sGroup: dungeon %s|r up to level %.1f, then the route continues."
T["Die Quests werden knapp. Für eure Gruppe passt jetzt Dungeon %s, mit den Dungeon Quests geht das schneller als grinden. Die Route gibt es im Fenster unter Dungeons."] = "Quests are running short. Dungeon %s fits your group now, with the dungeon quests it's faster than grinding. The route is in the window under Dungeons."
T["Wartet ..."] = "Waiting ..."
T["Wartet, bis alle Addons geladen sind. Danach rechnet die Route von selbst."] = "Waiting until all addons are loaded. Then the route calculates by itself."
T["Wartet, bis Questie fertig gestartet ist. Danach rechnet die Route von selbst."] = "Waiting until Questie has finished starting. Then the route calculates by itself."
T["Wegdaten werden vorbereitet, die Route rechnet gleich danach."] = "Preparing path data, the route calculates right after."
