T["Wartet auf deine Position (Ladebildschirm), dann rechnet die Route."] = "Waiting for your position (loading screen), then the route calculates."
T["Es wird noch geladen. Die Berechnung startet in ca %d Sek."] = "Still loading. The calculation starts in about %d sec."
T["Questie startet noch. Die Berechnung startet sobald Questie fertig ist, spätestens in %d Sek."] = "Questie is still starting. The calculation starts as soon as Questie is ready, at the latest in %d sec."
T["Wartet, bis alle Addons geladen sind. Die Berechnung startet in ca %d Sek."] = "Waiting until all addons are loaded. The calculation starts in about %d sec."
T["Wartet, bis Questie fertig gestartet ist. Die Berechnung startet spätestens in %d Sek."] = "Waiting until Questie has finished starting. The calculation starts at the latest in %d sec."
