T["Dein Weg bis Level 60 zum Anklicken: oben alles, was du schon gemacht hast, darunter was noch kommt, mit Zeit pro Level und Zone."] = "Your way to level 60 to click through: at the top everything you have already done, below what is still to come, with time per level and zone."
T["|cff9d9d9d%s, Level ca %.1f, laufende Route, Schritt %d|r"] = "|cff9d9d9d%s, level approx %.1f, current route, step %d|r"
T["Woanders starten, zum Beispiel mit Freunden im Startgebiet von einem anderen Volk. Die Route führt dich dorthin."] = "Start somewhere else, for example with friends in the starting area of another race. The route leads you there."
