T["Hier starten"] = "Start here"
T["Startgebiet"] = "Starting area"
T["Startgebiet wählen"] = "Choose starting area"
T["Taschen fast voll. Nächster Händler: %s, ca %d Yards. Im Menü auf Händler klicken, dann kommt er als Schritt dazu."] = "Bags almost full. Nearest vendor: %s, about %d yards. Click Vendor in the menu to add it as a step."
T["Taschen fast voll. Beim nächsten Händler verkaufen."] = "Bags almost full. Sell at the next vendor."
T["|cff40ff40%d zum Abgeben|r"] = "|cff40ff40%d to turn in|r"
T["jetzt benutzen, wo du stehst"] = "use it now, right where you are"
T["jetzt klicken"] = "click now"
T["%s noch nicht benutzen, kommt gleich dran"] = "Don't use your %s yet, it comes up soon"
T["Die Route braucht ihn in ein paar Schritten, dann kommt beim Pfeil ein Knopf. Vorher nicht benutzen, sonst ist er nicht bereit."] = "The route needs it in a few steps, then a button shows up at the arrow. Don't use it before, or it won't be ready."
T["Jetzt"] = "Now"
T["Knopf darunter klicken"] = "click the button below"
T["Geladene Route"] = "Loaded route"
T["%d Min"] = "%d min"
T["Die Route liegt auf einem anderen Kontinent. Nimmst du hier Quests an oder gibst welche ab, rechnet sie ab hier neu."] = "The route is on another continent. If you accept or turn in quests here, it recalculates from here."
T["Anderer Kontinent als geplant: Tour wird ab hier neu berechnet"] = "Different continent than planned: recalculating tour from here"
T["Anderer Kontinent als geplant: Route wird ab hier neu berechnet"] = "Different continent than planned: recalculating route from here"
T["anderer Kontinent"] = "different continent"

-- Umbau 17.0
T["|cffff5050Questlog fast voll: %d von %d.|r Unter Meine Route, Tab Planen: Questlog aufräumen."] = "|cffff5050Quest log almost full: %d of %d.|r Under My Route, Plan tab: Clean up quest log."
T["Tempo"] = "Pace"
T["Im Modus Experte ist alles sofort da."] = "In Expert mode everything is there right away."
T["Alles: jede machbare Quest. Normal: gute Quests. Schnell: die besten Quests, mit oder ohne Grinden. Questlog Route: nur was schon im Log ist. Leuchtend ist die aktive."] = "All: every doable quest. Normal: good quests. Fast: the best quests, with or without grinding. Quest log route: only what's already in your log. The lit one is active."
T["Die wichtigsten Knöpfe zum Starten. Gestrichelte kommen erst später und zeigen ihr Level. Alle Einstellungen unten im grossen Fenster."] = "The most important buttons to get started. Dashed ones come later and show their level. All settings are further down in the main window."
T["Mein Weg im grossen Fenster"] = "My Path in the main window"
T["Statistik im grossen Fenster"] = "Statistics in the main window"
T["Klein: Zone, Ziel, Weg und drei Knöpfe. Gross: dazu Danach, Mitnehmen, Gruppe, XP Balken und Tempo."] = "Small: zone, goal, path and three buttons. Large: plus Then, Along the way, group, XP bar and pace."
T["Skalierung vom Mini Fenster: %d%%"] = "Mini window scale: %d%%"
T["Skalierung vom Mini Fenster"] = "Mini window scale"
T["Macht das ganze Mini Fenster grösser oder kleiner, mit Schrift, Knöpfen und Hinweisen."] = "Makes the whole mini window bigger or smaller, with text, buttons and hints."
T["Ja: unten in der Seitenleiste kommt Farmen dazu, mit Berufe und Gold (Kräuter, Erz, Leder und mehr)."] = "Yes: Farming is added at the bottom of the sidebar, with Professions and Gold (herbs, ore, leather and more)."
T["Im Modus Geführt ab Level 35, im Modus Experte sofort."] = "In Guided mode from level 35, in Expert mode right away."
T["Tempo und Modus"] = "Pace and mode"
T["Hier wählst du das Tempo (Alles, Normal, Schnell) und den Modus (Geführt oder Experte). Maus auf einen Eintrag erklärt ihn."] = "Choose the pace here (All, Normal, Fast) and the mode (Guided or Expert). Hover an entry to see what it does."
T["Regler"] = "Slider"
T["Noch %d Level. Im Modus Experte ist alles sofort da."] = "%d more levels. In Expert mode everything is there right away."
T["Klick: zur Funktion"] = "Click: go to feature"
T["Kommt ab Level %d. Klick: Erklärung"] = "Comes at level %d. Click: explanation"
T["Experte: alle Funktionen sind da. Klick auf eine Karte springt zur Funktion."] = "Expert: all features are there. Click a card to jump to the feature."
T["Geführt: mit jeder Stufe kommt etwas dazu, das Fenster wächst mit. Klick auf eine Karte: freie springen zur Funktion, gesperrte zeigen, ab wann sie kommen."] = "Guided: every stage adds something and the window grows with it. Click a card: unlocked ones jump to the feature, locked ones show when they come."
T["Themen"] = "Topics"
T["Route gegen Plan"] = "Route vs plan"
T["   Viel Laufen: Tempo Schnell spart Wege."] = "   Lots of walking: Fast pace saves trips."
T["Klick: Tempo (Alles, Normal, Schnell) und Modus (Geführt oder Experte) wählen. Maus auf einen Eintrag erklärt ihn."] = "Click: choose pace (All, Normal, Fast) and mode (Guided or Expert). Hover an entry to see what it does."
T["Links alle Seiten. Im Modus Geführt kommen mit dem Level neue dazu, jede mit kurzer Erklärung."] = "All pages on the left. In Guided mode new ones are added as you level, each with a short explanation."
T["Gold/Std"] = "Gold/h"
T["(G) heisst: von dir gelernt.  "] = "(G) means: learned by you.  "
