T["|cff9d9d9dnoch offen|r"] = "|cff9d9d9dpending|r"
T["XP pro Stunde, wird gerade gemessen"] = "XP per hour, being measured"
T["Tour läuft"] = "Tour running"
T["Noch keine Route. Im Menü auf Neu rechnen."] = "No route yet. Click Recalculate in the menu."
T["Gerade: %s. Die Leveling Route wartet."] = "Right now: %s. The Leveling route is waiting."
