T["Questlog: %d Plätze, Warnung ab %d. Ändern mit /klg log 40 38 oder unter Einstellungen"] = "Quest log: %d slots, warning at %d. Change with /klg log 40 38 or under Settings"
T["Modus Experte: alles ist sofort da."] = "Expert mode: everything is there right away."
T["Modus Geführt: Funktionen kommen mit dem Level dazu, jede mit kurzer Erklärung."] = "Guided mode: features are added as you level, each with a short explanation."
T["/klg an | aus  Route zeigen oder verstecken,  /klg pause  alles anhalten oder weiter"] = "/klg an | aus  show or hide the route,  /klg pause  pause or resume everything"
T["/klg next | back  Schritt überspringen oder zurück"] = "/klg next | back  skip step or go back"
T["/klg einrichten  Einrichtung nochmal,  /klg gefuehrt | experte  Modus,  /klg look  Classic UI oder ElvUI"] = "/klg setup  redo setup,  /klg guided | expert  mode,  /klg look  Classic UI or ElvUI"
T["/klg einkaufen  Einkaufsliste,  /klg gear  Quests mit besserer Ausrüstung"] = "/klg einkaufen  Shopping list,  /klg gear  quests with better gear"
T["/klg farm  Gold: Mobs,  /klg farm stop  Farmen beenden"] = "/klg farm  Gold: Mobs,  /klg farm stop  stop farming"
T["/klg log 40 38  Questlog Plätze und Warnung,  /klg quests  Questlog prüfen"] = "/klg log 40 38  quest log slots and warning,  /klg quests  check quest log"
T["/klg check  Level prüfen,  /klg ignorieren  Warnung ausblenden,  /klg warnweg  Warnungen ausblenden"] = "/klg check  check level,  /klg ignorieren  hide warning,  /klg warnweg  hide warnings"
T["/klg auslassen  Quests beim Questgeber hier auslassen,  /klg questzuerst  Quests vor Händler und Lehrer"] = "/klg auslassen  skip the quests of the quest giver here,  /klg questzuerst  quests before vendor and trainer"
T["/klg gefahr  Gefahr hier markieren,  /klg gefahrweg  wieder löschen,  /klg punkte  Kartenpunkte als Symbole oder Ringe"] = "/klg gefahr  mark danger here,  /klg gefahrweg  remove it again,  /klg punkte  map points as icons or rings"
T["/klg erklaerungen  alle Erklärungen wieder zeigen,  /klg testlog notiz TEXT  Notiz ins Test Log"] = "/klg erklaerungen  show all explanations again,  /klg testlog notiz TEXT  note to the test log"
T["|cffffd100Testmodus:|r /klg tlvl 30 | aus  Test Level,  /klg diag  Questie prüfen,  /klg warum  warum so wenig Quests"] = "|cffffd100Test mode:|r /klg tlvl 30 | aus  test level,  /klg diag  check Questie,  /klg warum  why so few quests"
T["|cffffd100Testmodus:|r /klg rechnung  letzte Meldungen der Route,  /klg laut  Meldungen im Chat,  /klg testlog an | aus | leeren"] = "|cffffd100Test mode:|r /klg rechnung  latest route messages,  /klg laut  messages in chat,  /klg testlog an | aus | leeren"
T["|cffffd100Testmodus:|r /klg stats  gemessene XP Werte,  /klg id  MapID,  /klg wege  Wege teilen Stand,  /klg blockiert  blockierte Aktionen,  /klg pfeil  Pfeil prüfen"] = "|cffffd100Test mode:|r /klg stats  measured XP values,  /klg id  MapID,  /klg wege  Share paths status,  /klg blockiert  blocked actions,  /klg pfeil  check arrow"
T["|cffffd100Testmodus:|r /klg add Name | undo | clear | export | reset | radius 0.02 | wegweg  eigene Wegpunkte der Zone"] = "|cffffd100Test mode:|r /klg add Name | undo | clear | export | reset | radius 0.02 | wegweg  your own waypoints for the zone"
T["Questgeber, Abgaben, Questziele, die Route, Touren, Dungeons, Lehrer und Flugpunkte"] = "Quest givers, turn ins, objectives, the route, tours, dungeons, trainers and flight points"
