T["Gold Quests fertig! Neu berechnen unter Farmen, Gold."] = "Gold quests done! Recalculate under Farming, Gold."
T["Erste Schritte"] = "Getting started"
T["So geht es los|r"] = "How to start|r"
T[" müssen an sein. Fehlt etwas, sagt dir Forever Wegweiser beim Einloggen Bescheid."] = " must be enabled. If something is missing, Forever Wegweiser tells you when you log in."
T[": Tempo, allein oder Gruppe, Modus und Grösse vom Mini Fenster. Nochmal machen: oben rechts "] = ": pace, solo or group, mode and size of the mini window. To redo it: top right "
T[" oder "] = " or "
