T["Links ist die Seitenleiste: "] = "On the left is the sidebar: "
T[", die Ziele ("] = ", the goals ("
T["Ganz unten, mit einem Strich abgetrennt, steht "] = "At the very bottom, separated by a line, is "
T[" (Berufe und Gold). Das siehst du nur, wenn in den Einstellungen "] = " (Professions and Gold). You only see it if "
T["Farmberufe Routen"] = "Gathering routes"
T[" auf Ja ist."] = " is set to Yes in the settings."
T["Geführt und Experte|r"] = "Guided and Expert|r"
T["Geführt"] = "Guided"
T["  Am Anfang siehst du nur das Wichtigste. Mit dem Level kommen neue Funktionen dazu, jede mit einer kurzen Erklärung, und das Fenster wächst mit. "] = "  At first you only see the essentials. New features are added as you level, each with a short explanation, and the window grows with them. "
T[" zeigt, was wann kommt."] = " shows what comes when."
T["  Alles ist sofort da, auch Route exportieren und laden."] = "  Everything is there right away, including Export and load route."
T["Gesperrt ist nie etwas wirklich: Einstellungen kannst du immer ändern. Bei Geführt zeigt die Seite Einstellungen die wichtigsten, mit "] = "Nothing is ever really locked: you can always change settings. In Guided the Settings page shows the important ones, with "
T[" siehst du alle."] = " you see them all."
T["Wechseln: auf den Knopf oben im Fenster (Tempo und Modus), in den Einstellungen oder mit "] = "To switch: use the button at the top of the window (Pace and mode), the settings or "
T["Was kommt wann (Geführt)|r"] = "What comes when (Guided)|r"
T["Beim ersten Öffnen erklärt jedes Fenster kurz seine Knöpfe. Wieder einschalten: oben rechts auf dieser Seite "] = "On first open, each window briefly explains its buttons. To turn that back on: top right on this page "
T[" oder /klg erklaerungen.|r"] = " or /klg erklaerungen.|r"
T["Pfeil und Mini Fenster"] = "Arrow and mini window"
T["Der Pfeil|r"] = "The arrow|r"
T["Der Pfeil zeigt immer zum nächsten Schritt. Grün geradeaus, gelb seitlich, rot hinter dir. Darunter steht kurz, was zu tun ist, wie weit und wie lange ungefähr."] = "The arrow always points to the next step. Green straight ahead, yellow to the side, red behind you. Below it you see what to do, how far and about how long."
T["Das Symbol links vom Pfeil anklicken visiert den NPC oder Mob an. Zeigt der Pfeil auf einen Händler, Lehrer oder Wirt, ist es dieser. Als Geist zeigt der Pfeil zur Leiche."] = "Clicking the icon left of the arrow targets the NPC or mob. If the arrow points to a vendor, trainer or innkeeper, it targets that one. As a ghost the arrow points to your corpse."
T["Grösse vom Pfeil: Einstellungen, Route und Karte (50 bis 300 Prozent). Rechtsklick auf den Text sperrt den Pfeil oder gibt ihn frei, frei kannst du ihn ziehen."] = "Arrow size: Settings, Route and Map (50 to 300 percent). Right-click the text to lock or unlock the arrow, when unlocked you can drag it."
T["Das Mini Fenster|r"] = "The mini window|r"
T["Es gibt zwei Grössen: "] = "There are two sizes: "
T[" (Ziel, Weg und die Knöpfe) und "] = " (target, directions and the buttons) and "
T["Gross"] = "Large"
T[" (dazu Tipps, Gruppe, XP Balken und Tempo). Umstellen in den Einstellungen. Ziehen verschiebt, Rechtsklick sperrt."] = " (plus tips, group, XP bar and pace). Change it in the settings. Drag to move, right-click to lock."
T["Oben steht die Zone und der Schritt in dieser Zone, zum Beispiel "] = "At the top you see the zone and the step in that zone, for example "
T["Wald von Elwynn, Schritt 12 von 57"] = "Elwynn Forest, step 12 of 57"
T[", darunter "] = ", below it "
T["danach Westfall"] = "then Westfall"
T[". Der Balken darunter zeigt, wie weit du in der Zone bist."] = ". The bar below shows how far along you are in the zone."
T["Unten steht zum Beispiel "] = "At the bottom you see, for example, "
T["1 Quest fertig zum Abgeben"] = "1 quest ready to turn in"
T[". Maus drauf erklärt jede Zeile."] = ". Hover to explain each line."
T["Unten sind drei Knöpfe: "] = "At the bottom are three buttons: "
T[" (Schritt davor nochmal), "] = " (previous step again), "
T[" (nächster Schritt) und "] = " (next step) and "
T["Das Menü|r"] = "The menu|r"
T["  rechnet die Route ab hier neu."] = "  recalculates the route from here."
T["  lässt den jetzigen Schritt aus."] = "  skips the current step."
T["  Pfeil zum nächsten Händler, als Schritt in der Route."] = "  arrow to the nearest vendor, as a step in the route."
T["  Pfeil zum nächsten Gasthaus, mit Abgaben auf dem Weg und ob der Ruhestein schneller ist."] = "  arrow to the nearest inn, with turn ins on the way and whether your hearthstone is faster."
T["  Quest Items, die du kaufen musst."] = "  quest items you need to buy."
T["Ziel wählen"] = "Choose goal"
T["  Leveln, Dungeons, Ausrüstung, Bücher oder Ruf."] = "  leveling, dungeons, gear, books or reputation."
T["  öffnet das grosse Fenster."] = "  opens the main window."
T["  steht nur da, solange eine Farm Route läuft."] = "  only shows while a farm route is running."
T["Läuft gerade eine Tour oder eine Farm Route, steht oben im Menü auch, zwischen welchen Routen du wechseln kannst (siehe Route und Tempo)."] = "If a tour or farm route is running, the top of the menu also shows which routes you can switch between (see Route and pace)."
T["Der farbige Streifen|r"] = "The colored stripe|r"
T["Links im Mini Fenster ist ein farbiger Streifen. Die Farbe sagt, was der jetzige Schritt ist:"] = "On the left of the mini window is a colored stripe. The color tells you what the current step is:"
T["Die gleichen Farben haben auch die Linie und die Punkte auf der Karte."] = "The line and the points on the map use the same colors."
T["Hinweise|r"] = "Hints|r"
T["Über dem Mini Fenster steht jeder Hinweis als eigene Karte. X klickt sie weg, "] = "Above the mini window each hint shows as its own card. X dismisses it, "
T[" schickt dich hin. Kommt eine neue Funktion dazu, steht dort "] = " sends you there. When a new feature is added, it shows "
T["Neu: ..."] = "New: ..."
T[", Klick zeigt die Erklärung."] = ", click to see the explanation."
T["Karte und Minimap|r"] = "Map and minimap|r"
T["Die Karte zeigt die nächsten Schritte als Linie mit Nummern. Rechts an der Karte ist eine schmale Leiste mit Symbolen (Route, Minimap Linie, Bücher, Gold, OpenMap). Maus drauf erklärt sie, leuchtend heisst an."] = "The map shows the next steps as a numbered line. On the right side of the map is a narrow bar with icons (Route, Minimap line, Books, Gold, OpenMap). Hover to explain them, lit means on."
T["Die Minimap zeigt die nächsten Schritte als Linie und Questgeber als Kreise."] = "The minimap shows the next steps as a line and quest givers as circles."
T["Wege um Berge|r"] = "Paths around mountains|r"
T["Das Spiel hat keine Geländedaten. Darum lernt Forever Wegweiser, wo man laufen kann: wo du schon warst, wo Mobs und NPCs stehen und welche Übergänge zwischen Zonen du benutzt hast. Pfeil und Karte nehmen dann den bekannten Weg statt quer über den Berg."] = "The game has no terrain data. So Forever Wegweiser learns where you can walk: where you've been, where mobs and NPCs stand and which zone crossings you've used. The arrow and map then take the known path instead of going straight over the mountain."
T["Einen Berg sperrst du selbst mit "] = "You can block a mountain yourself with "
T["Alt+Klick"] = "Alt+click"
T[" auf der Karte, eine grosse Gefahr mit "] = " on the map, a big danger with "
T["Alt+Strg+Klick"] = "Alt+Ctrl+click"
T["Wege teilen"] = "Share paths"
T["  Wo du gelaufen bist, geht frühestens nach 45 Minuten an andere Spieler mit Forever Wegweiser. Eine Stelle gilt erst als frei, wenn viele Spieler an verschiedenen Tagen dort laufen. Einen Berg setzen andere nie. "] = "  Where you've walked is sent to other players with Forever Wegweiser after 45 minutes at the earliest. A spot only counts as clear once many players have walked there on different days. Others can never set a mountain. "
T[" zeigt den Stand."] = " shows the status."
T["Route und Tempo"] = "Route and pace"
T["Die Route|r"] = "The route|r"
T["Forever Wegweiser rechnet eine "] = "Forever Wegweiser calculates a "
T[" bis Level 60. Jeder Abschnitt geht ein paar Level, mit Laufwegen, Ketten, Ruf, Questlog Plätzen, Klassenquests und Lehrern. Zonenwechsel kosten extra, darum macht die Route erst eine Zone fertig."] = " up to level 60. Each section covers a few levels, with walking paths, chains, reputation, quest log slots, class quests and trainers. Changing zones costs extra, so the route finishes a zone first."
T["Die Seite "] = "The "
T[" hat drei Reiter: "] = " page has three tabs: "
T[" (alle Schritte vom Abschnitt), "] = " (all steps of the section), "
T[" (Level und Zonen bis 60) und "] = " (levels and zones up to 60) and "
T["Tempo|r"] = "Pace|r"
T["Ein Regler mit drei Stufen:"] = "A slider with three settings:"
T["  alle machbaren Quests, auch solche, die kaum noch XP geben. Zonen werden fertig gemacht, bevor es weiter geht."] = "  all doable quests, even ones that barely give XP anymore. Zones get finished before moving on."
T["  gute Quests in sinnvoller Reihenfolge. Grinden nur im Notfall, wenn es in deinem Level sonst keine Quests gibt. Das ist der Standard."] = "  good quests in a sensible order. Grinding only when needed, if there are no other quests at your level. This is the default."
T["  nur die besten Quests. Mit "] = "  only the best quests. With "
T["Grinden: Ja"] = "Grinding: Yes"
T[" kommen kurze Grind Pausen dazu, aber nur dort, wo Grinden klar schneller ist als Quests."] = " short grind breaks are added, but only where grinding is clearly faster than questing."
T["Bei jeder Stufe steht, wie viel schneller oder langsamer sie für dich ist als Normal, und wie lange es ungefähr bis 60 dauert (gespielte Zeit). Die Zahlen kommen aus deinen gemessenen Zeiten (Lauftempo, Kampf, Pausen). Am Anfang steht "] = "Each setting shows how much faster or slower it is for you than Normal, and about how long it takes to reach 60 (played time). The numbers come from your measured times (walking speed, combat, breaks). At first it says "
T[", bis genug gemessen ist."] = ", until enough has been measured."
T["Ein Grind Block ist nie länger als "] = "A grind block is never longer than "
T[". Danach geht es mit Quests weiter oder der nächste Block kommt an einem anderen Ort."] = ". Then it's back to quests, or the next block is in a different place."
T["Neu rechnen|r"] = "Recalculate|r"
T["Die Route rechnet sich nur von selbst neu, wenn du einen ganzen Level voraus oder hinten bist, wenn eine Tour fertig ist oder wenn du eine Einstellung änderst."] = "The route only recalculates by itself when you're a full level ahead or behind, when a tour is done or when you change a setting."
T["Bist du weit weg von der Route (oder stirbst weit weg), zeigt der Pfeil zurück zur Route und ein Hinweis fragt "] = "If you're far from the route (or die far away), the arrow points back to the route and a hint asks "
T["Neu rechnen?"] = "Recalculate?"
T[". Du kannst ihn wegklicken."] = ". You can dismiss it."
T["Kleine Abweichungen (eine Quest anders gemacht, ein Schritt schon erledigt): der Pfeil springt zum nächsten passenden Schritt."] = "Small changes (a quest done differently, a step already done): the arrow jumps to the next matching step."
T["Von Hand: Menü, "] = "Manually: menu, "
T["Planen|r"] = "Plan|r"
T["Im Reiter "] = "The "
T[" sind der Tempo Regler und die Touren:"] = " tab has the pace slider and the tours:"
T["  alle Quests aus deinem Log anhaken, dann Route berechnen."] = "  check all quests from your log, then calculate the route."
T["  Stunden und Minuten oder eine Uhrzeit: die Route passt in die Zeit und endet in einem Gasthaus."] = "  hours and minutes or a clock time: the route fits into that time and ends at an inn."
T["  kürzeste Tour zu allen fehlenden Flugpunkten."] = "  shortest tour to all missing flight points."
T["  kürzeste Tour zu allen noch nicht entdeckten Gebieten."] = "  shortest tour to all areas not explored yet."
T[" (Quests, die sich kaum lohnen, mit Knopf zum Abbrechen)."] = " (quests that are barely worth it, with a button to abandon them)."
T["  bei Experte sofort, bei Geführt ab Level 25. Eine geladene Route zeigt Namen in deiner Sprache."] = "  right away in Expert, from level 25 in Guided. A loaded route shows names in your language."
T["Leveling Route und Tour|r"] = "Leveling route and tour|r"
T["Die "] = "The "
T[" gibt es immer, bis Level 60. Startest du eine Tour oder eine Farm Route, kommt eine zweite Route dazu. Im Menü vom Mini Fenster wechselst du zwischen beiden."] = " is always there, up to level 60. If you start a tour or a farm route, a second route is added. Switch between them in the mini window menu."
T["Die Leveling Route merkt sich, wo du warst. Quests und Level, die du in der Tour machst, zählen trotzdem. Ist die Tour fertig, verschwindet sie und es geht mit der Leveling Route weiter."] = "The Leveling route remembers where you were. Quests and levels you do in the tour still count. When the tour is done, it goes away and you continue with the Leveling route."
T["Übersicht|r"] = "Overview|r"
T["Die Übersicht zeigt deine Ziele als Karten. Auf jeder Karte steht kurz der Stand, zum Beispiel "] = "The Overview shows your goals as cards. Each card shows a short status, for example "
T["Leveln: läuft"] = "Leveling: running"
T["Ausrüstung: 2 Upgrades"] = "Gear: 2 upgrades"
T["Bücher: 3 in der Nähe"] = "Books: 3 nearby"
T["Dungeons: in 2 Level"] = "Dungeons: in 2 levels"
T["Mein Weg|r"] = "My Path|r"
T["Alle Stufen bis 60 als Karten, mit einer Linie verbunden. Klick auf eine freie Karte springt zur Funktion, eine gesperrte zeigt, wann sie kommt und was sie macht."] = "All stages up to 60 as cards, connected by a line. Clicking an unlocked card jumps to the feature, a locked one shows when it comes and what it does."
T["Drei Reiter: "] = "Three tabs: "
T[". Dungeons ohne Quests für dich sind ausgeblendet."] = ". Dungeons with no quests for you are hidden."
T["Ein Dungeon zeigt, ob du alle Quests annehmen kannst, welcher Ruf und welche Vorquests noch fehlen, und alle Quests mit Ketten."] = "A dungeon shows whether you can accept all its quests, which reputation and prerequisite quests are still missing, and all quests with their chains."
T["  Vorquests, Annehmen, Dungeon, Abgeben.  "] = "  prerequisite quests, accept, dungeon, turn in.  "
T["  jeder holt einen Teil der Quests."] = "  everyone gets part of the quests."
T["Ausrüstung|r"] = "Gear|r"
T["Quests, deren Belohnung für dich besser ist als dein Teil. Gewertet nach den Werten für deine Klasse, Rüstungstyp und Waffen. Sortieren nach Level oder nach Verbesserung."] = "Quests whose reward is better for you than what you're wearing. Rated by the stats for your class, armor type and weapons. Sort by level or by upgrade."
T["  plant alle mit Haken, offene Vorquests kommen automatisch mit."] = "  plans all checked ones, missing prerequisite quests are added automatically."
T["Ruf|r"] = "Reputation|r"
T["Alle Fraktionen mit Quests, die Ruf geben. "] = "All factions with quests that give reputation. "
T[" plant die schnellste Route nur für diese Fraktion. Fraktionen mit Ruf für Mobs stehen mit "] = " plans the fastest route just for that faction. Factions that give reputation from mobs show "
T[" in der Liste, "] = " in the list, "
T[" schickt dich hin."] = " sends you there."
T["Bücher|r"] = "Books|r"
T["Die Bibliotheksbücher von Forever: Liste mit Haken, Ort und Abgabe. "] = "The library books of Forever: a list with checkboxes, location and turn in. "
T[" ist die kürzeste Runde zu den angehakten."] = " is the shortest loop to the checked ones."
T["Ein Buch ist auf der normalen Route einen kleinen Umweg wert (Standard 600 Yards, einstellbar unter Einstellungen, Bücher)."] = "On the normal route a book is worth a small detour (default 600 yards, adjustable under Settings, Books)."
T["Farmen steht unten in der Seitenleiste, wenn in den Einstellungen Farmberufe Routen auf Ja ist.|r"] = "Farming is at the bottom of the sidebar if Gathering routes is set to Yes in the settings.|r"
T["Berufe|r"] = "Professions|r"
T["Kräuter, Erz, Leder, Stoff, Fleisch und Fische farmen. Oben den Beruf wählen, links die Sachen anhaken. Nur was du mit deinem Skill kannst, ist wählbar."] = "Farm herbs, ore, leather, cloth, meat and fish. Choose the profession at the top, check the items on the left. Only what your skill allows can be selected."
T["Rechts zwei Reiter: "] = "On the right are two tabs: "
T[" (Level, Stellen, Status und "] = " (level, spots, status and "
T[") und "] = ") and "
T[" (mit AtlasLoot, welcher deiner Charaktere es kann)."] = " (with AtlasLoot, which of your characters knows it)."
T["Gold/Std ist ein Schätzwert mit Preisen aus dem Auktionshaus (TSM, Auctionator, Auctioneer, Aux oder OribosExchange). Ohne Auktionshaus Addon zählt der Händler Preis, dann ist der Wert zu tief."] = "Gold/h is an estimate using auction house prices (TSM, Auctionator, Auctioneer, Aux or OribosExchange). Without an auction house addon the vendor price is used, so the value is too low."
T["  Ziel nach Menge oder Zeit, Elitegebiete meiden, mehrere Berufe gemischt. Angeln: Open World oder Schwärme (braucht GatherMate2)."] = "  goal by amount or time, avoid elite areas, mix several professions. Fishing: Open World or schools (needs GatherMate2)."
T["Zwei Reiter: "] = "Two tabs: "
T["  Spots mit normalen Mobs, die du allein schaffst, sortiert nach Gold pro Stunde. Der Wert pro Kill wird aus deiner Beute gelernt. "] = "  spots with normal mobs you can handle solo, sorted by gold per hour. The value per kill is learned from your loot. "
T[" schickt dich hin, "] = " sends you there, "
T[" zeigt die Bilanz."] = " shows the summary."
T["  Quests mit viel Gold, mit Ziel nach Zeit oder Gold."] = "  quests with lots of gold, with a goal by time or gold."
T["Mit anderen spielen|r"] = "Playing with others|r"
T["Haben andere in der Gruppe Forever Wegweiser, siehst du im Mini Fenster ihren Stand bei gemeinsamen Quests. An einer Abgabe steht, auf wen du noch warten musst."] = "If others in your group have Forever Wegweiser, the mini window shows their progress on shared quests. At a turn in it shows who you still need to wait for."
T["Gruppen Route|r"] = "Group route|r"
T["Der Gruppenleiter rechnet für alle. Alle anderen sehen seine Schritte und springen mit ihm weiter. Was du nicht machen kannst, steht als 'hilf mit' da."] = "The group leader calculates for everyone. Everyone else sees the leader's steps and moves on with them. Anything you can't do shows as 'help out'."
T["Meldet sich der Leiter nicht mehr, läuft wieder deine eigene Route."] = "If the leader stops responding, your own route runs again."
T["Nur der Gruppenleiter kann eine Gruppen Route schicken."] = "Only the group leader can send a group route."
T["So sind die Einstellungen aufgebaut|r"] = "How the settings work|r"
T["Alle Einstellungen sind Fragen mit Ja und Nein, nach Thema sortiert. Maus auf die Frage erklärt sie."] = "All settings are yes or no questions, sorted by topic. Hover a question to see what it does."
T["Bei Geführt siehst du die wichtigsten. "] = "In Guided you see the important ones. "
T[" zeigt alle, "] = " shows all of them, "
T[" wieder die kurze Liste."] = " goes back to the short list."
T["Die wichtigsten|r"] = "The important ones|r"
T["  Alles, Normal oder Schnell (bei Schnell auch Grinden Ja oder Nein)."] = "  All, Normal or Fast (with Fast also Grinding yes or no)."
T["  Geführt oder Experte."] = "  Guided or Expert."
T["  Klein oder Gross."] = "  Small or Large."
T["  nimmt Quests aus deiner Route und Klassenquests selbst an und gibt sie ab."] = "  accepts and turns in quests from your route and class quests by itself."
T["  Flüge, Ruhestein, Taschen (Händler einplanen), Reittier, Bücher unterwegs mitnehmen, Wege teilen."] = "  flights, hearthstone, bags (plan vendor stops), mount, pick up books on the way, Share paths."
T["  zeigt Farmen in der Seitenleiste."] = "  shows Farming in the sidebar."
T["  mit ElvUI der ElvUI Look, sonst Classic wie die Blizzard Fenster. Gilt nach /reload."] = "  with ElvUI the ElvUI look, otherwise Classic like the Blizzard windows. Takes effect after /reload."
T["Änderst du eine Einstellung, die die Route betrifft, rechnet sie sich neu.|r"] = "If you change a setting that affects the route, it recalculates.|r"
T["Befehle"] = "Commands"
T["  öffnet das grosse Fenster.  "] = "  opens the main window.  "
T["  Liste der Befehle im Chat."] = "  list of commands in chat."
T["  diese Seite."] = "  this page."
T["  Route zeigen oder verstecken.  "] = "  show or hide the route.  "
T["  alles anhalten oder weiter."] = "  pause or resume everything."
T["  Schritt überspringen oder zurück."] = "  skip step or go back."
T["  Einrichtung nochmal.  "] = "  Setup again.  "
T["  Modus.  "] = "  mode.  "
T["  Classic oder ElvUI."] = "  Classic or ElvUI."
T["  Einkaufsliste.  "] = "  Shopping list.  "
T["  Quests mit besserer Ausrüstung."] = "  quests with better gear."
T["  Farmen beenden."] = "  stop farming."
T["  Questlog Plätze und ab wann gewarnt wird.  "] = "  quest log slots and when to warn.  "
T["  Questlog prüfen."] = "  check quest log."
T["  Quests beim Questgeber hier auslassen.  "] = "  skip the quests of the quest giver here.  "
T["  Quests vor Händler und Lehrer."] = "  quests before vendor and trainer."
T["  Gefahr hier markieren.  "] = "  mark danger here.  "
T["  wieder löschen."] = "  remove it again."
T["  alle Erklärungen wieder zeigen."] = "  show all explanations again."
T["  schreibt eine Notiz ins Test Log, zum Beispiel wenn etwas komisch war. Das Test Log kannst du im Discord hochladen, es enthält keine Namen von anderen Spielern."] = "  writes a note to the test log, for example when something was weird. You can upload the test log on Discord, it contains no names of other players."
T["Weitere Befehle zum Testen gibt es erst nach /klg testmodus. Sie stehen nicht in dieser Liste und sind nur für Fehlersuche gedacht.|r"] = "More test commands only become available after /klg testmodus. They're not in this list and are only meant for troubleshooting.|r"
T["Häufige Fragen"] = "Common questions"
T["Der Pfeil zeigt quer über einen Berg.|r"] = "The arrow points straight over a mountain.|r"
T["Forever Wegweiser kennt noch keinen Weg dort. Lauf einmal den richtigen Weg, dann lernt er ihn. Oder setze mit Alt+Klick auf der Karte eine Gefahr."] = "Forever Wegweiser doesn't know a path there yet. Walk the right way once and it learns it. Or set a danger with Alt+click on the map."
T["Die Route will, dass ich grinde.|r"] = "The route wants me to grind.|r"
T["Bei Normal kommt das nur, wenn es in deinem Level keine passenden Quests gibt. Ein Grind Block ist kurz (höchstens "] = "On Normal this only happens if there are no fitting quests at your level. A grind block is short (at most "
T["). Dungeons gehen auch: bist du danach voraus, fällt der Grind Schritt weg."] = "). Dungeons work too: if you're ahead afterwards, the grind step is dropped."
T["Ich habe etwas anderes gemacht als die Route.|r"] = "I did something different from the route.|r"
T["Kein Problem. Kleine Abweichungen merkt die Route selbst und springt zum nächsten passenden Schritt. Bist du einen ganzen Level weiter oder hinten, rechnet sie sich neu."] = "No problem. The route notices small changes by itself and jumps to the next matching step. If you're a full level ahead or behind, it recalculates."
T["Warum ist eine Funktion gesperrt?|r"] = "Why is a feature locked?|r"
T["Bei Geführt kommen Funktionen mit dem Level. Mein Weg zeigt, wann. Im Modus Experte ist alles sofort da."] = "In Guided, features come as you level. My Path shows when. In Expert mode everything is there right away."
T["Wie genau sind die Zeiten?|r"] = "How accurate are the times?|r"
T["Am Anfang sind es Schätzwerte. Je länger du spielst, desto genauer, weil Forever Wegweiser dein Lauftempo, dein Reittier, die Kampfzeit pro Mob und deine Pausen misst."] = "At first they're estimates. The longer you play, the more accurate they get, because Forever Wegweiser measures your walking speed, your mount, combat time per mob and your breaks."
T["Die Route rechnet nicht oder ist leer.|r"] = "The route doesn't calculate or is empty.|r"
T["Prüfe, ob Questie und QuestieDB an sind. Nach dem Einloggen braucht Questie ein paar Sekunden. Menü, Neu rechnen versucht es nochmal."] = "Check that Questie and QuestieDB are enabled. After logging in Questie needs a few seconds. Menu, Recalculate tries again."
T["Ich habe einen Fehler gefunden.|r"] = "I found a bug.|r"
T["Schreib mit /klg testlog notiz kurz, was passiert ist. Das Test Log liegt in WTF\\Account\\<Konto>\\SavedVariables\\KeineZeitLevelingGuide_Log.lua. Schick genau diese Datei, nicht KeineZeitLevelingGuide.lua (das sind nur deine Einstellungen). Vorher ausloggen oder /reload, dann ist alles drin."] = "Write what happened with /klg testlog notiz. The test log is in WTF\\Account\\<account>\\SavedVariables\\KeineZeitLevelingGuide_Log.lua. Send exactly this file, not KeineZeitLevelingGuide.lua (that is only your settings). Log out or /reload first, then everything is in it."
T["Zum Schicken: KeineZeitLevelingGuide_Log.lua aus WTF, Account, dein Konto, SavedVariables. Nicht KeineZeitLevelingGuide.lua, das sind nur die Einstellungen."] = "To send it: KeineZeitLevelingGuide_Log.lua from WTF, Account, your account, SavedVariables. Not KeineZeitLevelingGuide.lua, that is only the settings."
T["%d Minuten"] = "%d minutes"
T["Namensplaketten für freundliche NPCs eingeschaltet (Spieler bleiben wie sie sind), damit der Questgeber markiert werden kann. Ausschalten unter Einstellungen: Questgeber markieren."] = "Nameplates for friendly NPCs turned on (players stay as they are) so the quest giver can be marked. Turn off under Settings: Mark quest givers."
T[" Der Pfeil führt dich zurück zur Route. Im Mini Fenster kannst du neu rechnen lassen."] = " The arrow leads you back to the route. You can recalculate in the mini window."
T[" Neu rechnen?"] = " Recalculate?"
T["Klick: ab hier neu rechnen. X: nein, der Pfeil führt zurück zur Route."] = "Click: recalculate from here. X: no, the arrow leads back to the route."
T["Tempo "] = "Pace "
T["Tempo Alles"] = "Pace All"
T["Tempo Schnell"] = "Pace Fast"
T["Schritt %d von %d: %s"] = "Step %d of %d: %s"
T["Noch keine Route. Menü, Neu rechnen."] = "No route yet. Menu, Recalculate."
T["Abschnitt %d von %d"] = "Section %d of %d"
T["Nach dem Tod weit weg von der Route."] = "Far from the route after dying."
T["Die Route liegt auf einem anderen Kontinent. Der Pfeil führt dich zurück. Spielst du hier weiter, kommt der Hinweis Neu rechnen."] = "The route is on another continent. The arrow leads you back. If you keep playing here, the Recalculate hint shows up."
T["Du spielst auf einem anderen Kontinent als die Route."] = "You're playing on a different continent than the route."
T["erste Route"] = "first route"
T["Route Start ab Level %.1f (%s)"] = "Route start from level %.1f (%s)"
T["Route fertig: Level %d bis %d, %d Schritte in %d Abschnitten."] = "Route done: level %d to %d, %d steps in %d sections."
T["Route fertig in %.0fs: %d Abschnitte, %d Schritte, bis Level %.1f"] = "Route done in %.0fs: %d sections, %d steps, up to level %.1f"
T["Die ganze Route konnte nicht gerechnet werden, sie rechnet jetzt Abschnitt für Abschnitt."] = "The whole route couldn't be calculated, it's now calculating section by section."
T["Route wird berechnet: Level %d bis %d ..."] = "Calculating route: level %d to %d ..."
T["%d Quests im Log sind nicht in der Route."] = "%d quests in your log aren't in the route."
T["Abschnitt %d live für die Gruppe"] = "Section %d live for the group"
T["Abschnitt %d von %d geladen: Level %.1f bis %.1f, %d Schritte"] = "Section %d of %d loaded: level %.1f to %.1f, %d steps"
T["Abschnitt %d von %d (angepasst)"] = "Section %d of %d (adjusted)"
T["Du bist ein ganzes Level %s als die Route (Level %.1f statt %.1f). Der Abschnitt wird ab hier neu gerechnet."] = "You're a full level %s than the route (level %.1f instead of %.1f). The section is recalculated from here."
T["%s: weiter, wo du warst (Schritt %d von %d)."] = "%s: continuing where you left off (step %d of %d)."
T["Es läuft gerade keine Tour oder Farm Route."] = "No tour or farm route is running right now."
T["Welches Tempo willst du?"] = "Which pace do you want?"
T["Bei jeder Stufe steht, wie viel schneller oder langsamer sie für dich ist als Normal und wie lange es ungefähr bis 60 dauert. Du kannst das später jederzeit ändern."] = "Each setting shows how much faster or slower it is for you than Normal and about how long it takes to reach 60. You can change this any time later."
T[" Der Regler lässt sich jederzeit verschieben, oben im Fenster, unter Meine Route, Planen oder in den Einstellungen."] = " You can move the slider any time: at the top of the window, under My Route, Plan or in the settings."
T["Ja: unten in der Seitenleiste kommt Farmen dazu, mit Berufe und Gold (Kräuter, Erz, Leder und mehr). Bei Geführt ab Level 10."] = "Yes: Farming is added at the bottom of the sidebar, with Professions and Gold (herbs, ore, leather and more). In Guided from level 10."
T["Gilt für jedes Tempo und jeden Modus. Ändern geht später unter Einstellungen."] = "Applies to every pace and mode. You can change it later under Settings."
T["Am Anfang nur das Wichtigste. Mit dem Level kommen neue Seiten dazu, jede mit kurzer Erklärung."] = "Only the essentials at first. New pages are added as you level, each with a short explanation."
T["Alles sofort da, alle Seiten und Einstellungen, auch Route exportieren und laden."] = "Everything right away, all pages and settings, including Export and load route."
T["Pfeil plus Ziel, Weg und die drei Knöpfe"] = "Arrow plus goal, path and the three buttons"
T["dazu Tipps, Gruppe, XP Balken und Tempo"] = "plus tips, group, XP bar and pace"
T["Experte: alle Seiten und Einstellungen sofort."] = "Expert: all pages and settings right away."
T[" Ausrüstung und Berufe 10, Bücher 12, Dungeons 15, Statistik 25, Ruf 30, Gold 35. Einstellungen: die wichtigsten, mit Knopf für alle."] = " Gear and Professions 10, Books 12, Dungeons 15, Statistics 25, Reputation 30, Gold 35. Settings: the important ones, with a button for all."
T["Mulgore, Schritt 3 von 24"] = "Mulgore, step 3 of 24"
T["danach Brachland"] = "then The Barrens"
T["Klein: Pfeil plus Fenster mit Ziel, Weg und den drei Knöpfen."] = "Small: arrow plus a window with goal, path and the three buttons."
T["Gross: dazu Tipps, Gruppe, XP Balken und Tempo."] = "Large: plus tips, group, XP bar and pace."
T["Auktionshaus Addon"] = "Auction house addon"
T["Auctionator, TSM, Auctioneer, Aux oder OribosExchange. Damit kennen Gold und Berufe die Preise für Stoff, Kräuter und Leder."] = "Auctionator, TSM, Auctioneer, Aux or OribosExchange. Gold and Professions use them for cloth, herb and leather prices."
T["Oder AtlasLoot Continued. Kennt alle Rezepte mit Zutaten. Ohne AtlasLoot siehst du nur die Rezepte, die du schon gelernt hast."] = "Or AtlasLoot Continued. Knows all recipes with their reagents. Without AtlasLoot you only see the recipes you've already learned."
T["Unten der Reiter Forever Wegweiser. Oder /klg für das grosse Fenster."] = "The Forever Wegweiser tab at the bottom. Or /klg for the main window."
T["Experte: alles ist schon da"] = "Expert: everything is already there"
T["Auch Dungeons, Ruf, Berufe, Gold und Route exportieren und laden gehen sofort."] = "Dungeons, Reputation, Professions, Gold and Export and load route work right away too."
T["Einschalten unter Einstellungen, Reisen: Wege teilen."] = "Turn it on under Settings, Travel: Share paths."
T[" mit Grinden"] = " with grinding"
T["%s, Tempo %s"] = "%s, pace %s"
T["   Grinden: "] = "   Grinding: "
T["Nur bei Schnell: kurze Grind Pausen dort, wo Grinden deutlich schneller ist als Quests. Nein: nur Quests."] = "Only with Fast: short grind breaks where grinding is clearly faster than questing. No: quests only."
T["Nur bei Schnell: Ja gibt kurze Grind Pausen dort, wo Grinden deutlich schneller ist als Quests. Nein: nur Quests. Bei Alles und Normal gibt es Grinden nur im Notfall."] = "Only with Fast: Yes adds short grind breaks where grinding is clearly faster than questing. No: quests only. With All and Normal, grinding only happens when needed."
T["Tempo: "] = "Pace: "
T["Grinden: "] = "Grinding: "
T["Route wird gerechnet ..."] = "Calculating route ..."
T["|cffffd100Questlog fast voll (%d von %d).|r Unter Meine Route, Planen: Questlog aufräumen."] = "|cffffd100Quest log almost full (%d of %d).|r Under My Route, Plan: Clean up quest log."
T["Tour beendet, es geht mit der Leveling Route weiter."] = "Tour ended, continuing with the Leveling route."
T["Zurück zur Leveling Route, beim Schritt, wo du warst."] = "Back to the Leveling route, at the step where you left off."
T["Quests für passende Dungeons holen und zum Eingang."] = "Get quests for fitting dungeons and go to the entrance."
T["Quests und Mobs für eine Fraktion."] = "Quests and mobs for a faction."
T["Kräuter, Erz, Leder, Stoff, Fleisch und Fische farmen."] = "Farm herbs, ore, leather, cloth, meat and fish."
T["Die besten Spots und Quests für Gold."] = "The best spots and quests for gold."
T["Route nur mit den Quests, die schon in deinem Log sind."] = "Route with only the quests already in your log."
T["Eine Runde zu allen Flugpunkten, die dir fehlen."] = "A loop to all flight points you're missing."
T["Wie lange willst du spielen? Die Route endet im Gasthaus."] = "How long do you want to play? The route ends at an inn."
T["Lehrer als Schritt"] = "Trainer as step"
T["Nächster Lehrer deiner Klasse kommt als Schritt in deine Route."] = "The nearest trainer for your class is added as a step to your route."
T["Hält alles an, nichts wird mehr gerechnet. Nochmal klicken macht weiter."] = "Stops everything, nothing is calculated. Click again to resume."
T["Zurück zur Leveling Route, beim Schritt, wo du warst. Was du dazwischen gemacht hast, zählt mit."] = "Back to the Leveling route where you left off. What you did meanwhile still counts."
T["Zurück zu deiner Tour oder Farm Route. Die Leveling Route bleibt gemerkt."] = "Back to your tour or farm route. The Leveling route is kept."
T["Diesen Schritt auslassen, der Pfeil zeigt zum nächsten."] = "Skip this step, the arrow points to the next one."
T["Ausrüstung, Bücher, Dungeons, Ruf, Berufe, Gold, Touren, Stunden Budget, Lehrer und Pause."] = "Gear, Books, Dungeons, Reputation, Professions, Gold, tours, Time budget, trainer and pause."
T["Beendet die Farm Route oder Tour. Danach geht die Leveling Route weiter."] = "Ends the farm route or tour. The Leveling route continues."
T["Farbe vom Schritt"] = "Step color"
T["Schritt %d von %d in dieser Zone. Der Balken zeigt, wie weit du hier bist."] = "Step %d of %d in this zone. The bar shows how far along you are."
T["Danach geht es nach %s."] = "Then on to %s."
T["Ganze Route bis 60: Schritt %d von %d"] = "Whole route to 60: step %d of %d"
T["Dein Tempo in den letzten Minuten. Daraus kommt die Zeit bis zum nächsten Level."] = "Your pace over the last few minutes. The time to the next level comes from this."
T["Fertig zum Abgeben"] = "Ready to turn in"
T["%d Quests im Log sind fertig. Abgeben bringt die XP, der helle Teil im Balken zeigt, wo du danach bist."] = "%d quests in your log are done. Turn them in for the XP, the bright part of the bar shows where you'll be."
T["Lauftempo"] = "Movement speed"
T["100% ist zu Fuss, mit Reittier mehr. Die Route rechnet die Wege damit."] = "100% is on foot, more with a mount. The route uses it for travel times."
T["Tour beenden"] = "End tour"
T["danach %s"] = "then %s"
T["|cff40ff401 Quest fertig zum Abgeben|r"] = "|cff40ff401 quest ready to turn in|r"
T["|cff40ff40%d Quests fertig zum Abgeben|r"] = "|cff40ff40%d quests ready to turn in|r"
T["Lauftempo %d%%"] = "Speed %d%%"
T["Im Mini Fenster Menü auf Einkaufsliste klicken."] = "In the mini window menu, click Shopping list."
T["Im grossen Fenster unter Ziele auf Ausrüstung klicken."] = "In the main window under Goals, click Gear."
T["Im grossen Fenster unter Ziele auf Bücher klicken."] = "In the main window under Goals, click Books."
T["Standard: ein Buch darf bis 600 Yards Umweg sein. Im Modus Experte stellst du das unter Einstellungen selbst ein."] = "Default: a book can be a detour of up to 600 yards. In Expert mode you set this yourself under Settings."
T["Im grossen Fenster unter Ziele auf Dungeons klicken."] = "In the main window under Goals, click Dungeons."
T["Kräuter, Erz, Leder, Stoff, Fleisch und Fische farmen. Du wählst, was du brauchst, Forever Wegweiser plant die Runde, auch für mehrere Berufe."] = "Farm herbs, ore, leather, cloth, meat and fish. Pick what you need, Forever Wegweiser plans the loop, even for several professions."
T["Im grossen Fenster unter Farmen auf Berufe klicken (Farmen erscheint, wenn Farmberufe Routen auf Ja steht)."] = "In the main window under Farming, click Professions (Farming shows up when Gathering routes is set to Yes)."
T["Level, Tempo, Zeit bis zum nächsten Level, dein Schritt und deine Ziele auf einer Seite."] = "Level, pace, time to the next level, your step and your goals on one page."
T["Wie gut läuft es? XP pro Stunde, Zeit bis zum nächsten Level und Vergleich mit der Route."] = "How's it going? XP per hour, time to the next level and comparison with the route."
T["Im grossen Fenster unter Start auf Statistik klicken."] = "In the main window under Start, click Statistics."
T["Deine Route bis Level 60 zum Anklicken: was du schon gemacht hast und was noch kommt, mit Zeit pro Level und Zone."] = "Your route up to level 60 to click through: what you've done and what's still coming, with time per level and zone."
T["Im grossen Fenster unter Meine Route, Reiter Zonenplan."] = "In the main window under My Route, Zone plan tab."
T["Statistik: Pro Level und Gesamt"] = "Statistics: Per level and Total"
T["Mehr Zahlen: Zeiten pro Abschnitt und Zone, Quests pro Gebiet und XP Anteile."] = "More numbers: times per section and zone, quests per area and XP shares."
T["Im grossen Fenster unter Statistik, Reiter Pro Level und Gesamt."] = "In the main window under Statistics, tabs Per level and Total."
T["Funktionen kommen mit dem Level dazu, jede kurz erklärt. Bei den Einstellungen erst die wichtigsten, der Rest unter Alle Einstellungen."] = "Features unlock as you level, each briefly explained. Settings show the important ones first, the rest under All settings."
T["Alles sofort da: alle Seiten, alle Funktionen, alle Einstellungen."] = "Everything right away: all pages, all features, all settings."
T["Wirklich alle machbaren Quests, auch mit wenig XP. Zonen werden fertig gemacht, bevor es weitergeht. Elite Quests kommen, sobald du sie allein schaffst."] = "Really every doable quest, even low XP ones. Zones get finished before moving on. Elite quests come once you can solo them."
T["Gute Quests in sinnvoller Reihenfolge. Grinden nur im Notfall, wenn es in deinem Level sonst keine Quests gibt. Standard."] = "Good quests in a sensible order. Grinding only when needed, if there are no other quests at your level. Default."
T["Nur die besten Quests. Mit Grinden auf Ja kommen kurze Grind Pausen dazu, aber nur dort, wo Grinden deutlich schneller ist als Quests."] = "Only the best quests. With Grinding set to Yes, short grind breaks are added, but only where grinding is clearly faster than questing."
T["unter 1 Std"] = "under 1 h"
T["ca %d Std"] = "about %d h"
T["ca 1 Tag"] = "about 1 day"
T["ca %d Tage"] = "about %d days"
T["ca 1 Tag %d Std"] = "about 1 day %d h"
T["ca %d Tage %d Std"] = "about %d days %d h"
T["etwa gleich schnell"] = "about the same speed"
T["ca %d%% langsamer"] = "about %d%% slower"
T["ca %d%% schneller"] = "about %d%% faster"
T["%s: %s, bis 60 %s gespielt"] = "%s: %s, %s played to 60"
T[", Abschnitt %s"] = ", section %s"
T["Kills pro Stunde, noch zu wenig Kills"] = "Kills per hour, not enough kills yet"
T["Quests pro Stunde, noch keine Quest abgegeben"] = "Quests per hour, no quest turned in yet"
T["|cffff9030Geht erst ab Level %d|r, noch %d XP. Kurz grinden oder Schritt überspringen."] = "|cffff9030Available from level %d|r, %d XP to go. Grind a bit or skip the step."
T["XP/Std: misst"] = "XP/h: measuring"
T["|cffffd100%s ist auch an.|r Das ist ok. Setzt es eigene Wegpunkte, siehst du dort einen zweiten Pfeil. Der Pfeil vom Forever Wegweiser zeigt immer auf die Route."] = "|cffffd100%s is also enabled.|r That's fine. If it sets its own waypoints, you'll see a second arrow there. The Forever Wegweiser arrow always points along the route."
T["|cffffd100%s ist auch an.|r Zwei Leveling Guides gleichzeitig zeigen zwei Pfeile und verschiedene Routen. Tipp: einen davon ausschalten. Forever Wegweiser läuft trotzdem normal weiter."] = "|cffffd100%s is also enabled.|r Two leveling guides at once show two arrows and different routes. Tip: turn one of them off. Forever Wegweiser keeps working normally."
T["Ich habe auch RestedXP, Zygor oder TomTom an.|r"] = "I also have RestedXP, Zygor or TomTom enabled.|r"
T["Das geht, aber zwei Leveling Guides zeigen zwei Pfeile und verschiedene Routen. Forever Wegweiser sagt einmal Bescheid und läuft normal weiter. Am einfachsten ist ein Guide zur Zeit."] = "That works, but two leveling guides show two arrows and different routes. Forever Wegweiser tells you once and keeps working. One guide at a time is easiest."
T["Questie hat keine Dungeon Liste. Questie und QuestieDB aktualisieren, dann /reload."] = "Questie has no dungeon list. Update Questie and QuestieDB, then /reload."
-- 17.2 Tempo, Grinden, Dungeon Quests
T["Hier wählst du Tempo und Modus. Maus auf einen Eintrag erklärt ihn."] = "Pick pace and mode here. Hover an entry to learn more."
T["   Viel Laufen: mit Grinden an spart die Route weite Wege."] = "   Lots of walking: with grinding on the route saves long walks."
T["Klick: Tempo und Modus wählen. Maus auf einen Eintrag erklärt ihn."] = "Click: choose pace and mode. Hover an entry to learn more."
T["Alles oder Normal, Grinden an oder aus"] = "All or Normal, grinding on or off"
T["Alles: jede machbare Quest. Normal: gute Quests. Questlog Route: nur was schon im Log ist. Leuchtend ist die aktive."] = "All: every doable quest. Normal: good quests. Quest log route: only what's already in your log. The lit one is active."
T["Dungeon Quests einplanen?"] = "Plan dungeon quests?"
T["Ja: Quests für Dungeons werden mit einem kleinen Umweg angenommen, damit du sie dabei hast, wenn du in den Dungeon gehst. Nein: nur die Vorquests, wenn sie sich lohnen. Die Quest, mit der es in den Dungeon geht, wird nicht angenommen. Angenommene bleiben immer drin."] = "Yes: dungeon quests are picked up with a small detour, so you have them when you go into the dungeon. No: only the prequests if they are worth it on their own. The quest that sends you into the dungeon is not picked up. Accepted quests always stay."
T["Ja: Quests für Dungeons werden mit einem kleinen Umweg angenommen, damit du sie dabei hast, wenn du in den Dungeon gehst. Nein: nur die Vorquests, wenn sie sich lohnen. Die Quest, mit der es in den Dungeon geht, wird nicht angenommen."] = "Yes: dungeon quests are picked up with a small detour, so you have them when you go into the dungeon. No: only the prequests if they are worth it on their own. The quest that sends you into the dungeon is not picked up."
T["Grinden an"] = "Grinding on"
T["  Grinden ist eine Option: die Route nimmt Grind Schritte, wo Grinden bei dir schneller ist als eine Quest. Bei schnellen Kill Zeiten kommen öfter Grind Schritte. Bei Alles nur, wenn es im Level sonst keine Quests gibt."] = "  Grinding is an option: the route takes grind steps where grinding is faster for you than a quest. With fast kill times grind steps come more often. With All only when there are no other quests for your level."
T["Grinden aus"] = "Grinding off"
T["  keine Grind Schritte, nur Quests."] = "  no grind steps, only quests."
T["Dungeon Quests einplanen"] = "Plan dungeon quests"
T["  Ja: Quests für Dungeons werden mit einem kleinen Umweg angenommen, damit du sie dabei hast. Nein: nur die Vorquests, wenn sie sich lohnen, die Quest für den Dungeon wird nicht angenommen."] = "  Yes: dungeon quests are picked up with a small detour, so you have them with you. No: only the prequests if they are worth it, the dungeon quest itself is not picked up."
T["Nach einem Grind Schritt: braucht die nächste Quest noch ein höheres Level, wird nur dieser Abschnitt neu gerechnet, höchstens alle 15 Minuten und höchstens zweimal pro Abschnitt."] = "After a grind step: if the next quest still needs a higher level, only this section is recalculated, at most every 15 minutes and at most twice per section."
T["  Alles oder Normal, dazu Grinden an oder aus."] = "  All or Normal, plus grinding on or off."
T["Mit Grinden an kommen Grind Schritte, wo Grinden bei dir schneller ist als eine Quest, bei schnellen Kill Zeiten öfter. Ein Grind Block ist kurz (höchstens "] = "With grinding on you get grind steps where grinding is faster for you than a quest, more often with fast kill times. A grind block is short (at most "
T["). Willst du nur Quests: beim Tempo Grinden aus. Dungeons gehen auch: bist du danach voraus, fällt der Grind Schritt weg."] = "). Want only quests: turn grinding off with the pace. Dungeons work too: if you are ahead afterwards, the grind step is dropped."
T["Ein Regler mit zwei Stufen und der Schalter Grinden:"] = "A slider with two steps and the grinding switch:"
T["Dungeon Quest, nur annehmen"] = "Dungeon quest, pick up only"
T[" |cff7fd1b9(Dungeon)|r"] = " |cff7fd1b9(dungeon)|r"
T["Die Leveling Route ist fertig, du bist auf Max Level.\n\nAuf Tempo Alles umschalten? Dann plant die Route alle restlichen Quests, die du noch machen kannst."] = "The leveling route is done, you are at max level.\n\nSwitch to pace All? Then the route plans all remaining quests you can still do."
T["Ja, alle Quests"] = "Yes, all quests"
T["Bei beiden: Pfeil, Abgaben, Folgequests, Klassenquests, Questlog bis 40 und Entdecken auf dem Weg."] = "With both: arrow, turn-ins, follow-up quests, class quests, quest log up to 40 and exploring on the way."
T[" ohne Grinden"] = " without grinding"
T["Gute Quests in sinnvoller Reihenfolge, der Standard. Mit Grinden an kommen Grind Schritte dazu, wo das für dich schneller ist."] = "Good quests in a sensible order, the default. With grinding on, grind steps are added where that's faster for you."
T["An: die Route nimmt Grind Schritte, wo Grinden für dich schneller ist als eine Quest. Bei Alles nur, wenn es sonst keine Quests gibt.\n\nAus: nur Quests, kein Grinden."] = "On: the route adds grind steps where grinding is faster for you than a quest. With All only when there are no other quests.\n\nOff: quests only, no grinding."
-- 17.2 Gruppe und Dungeon Quests
T["Nur der Gruppenleiter kann die Dungeon Quests aufteilen."] = "Only the group leader can split the dungeon quests."
T[" Aufteilen kann nur der Gruppenleiter."] = " Only the group leader can split."
T[" Standard ist Ja, der Modus ändert daran nichts."] = " Default is Yes, the mode does not change this."
T["Für das Test Log braucht es das Addon KeineZeitLevelingGuide_Log (eigener Ordner in AddOns, im Charakter Menü bei AddOns einschalten)."] = "The test log needs the addon KeineZeitLevelingGuide_Log (its own folder in AddOns, enable it in the AddOns list at character select)."
T["Test Log %s, %d Zeilen, Sitzung %s. Gespeichert wird beim Ausloggen oder /reload in WTF, SavedVariables, KeineZeitLevelingGuide_Log.lua (verschlüsselt)."] = "Test log %s, %d lines, session %s. Saved on logout or /reload in WTF, SavedVariables, KeineZeitLevelingGuide_Log.lua (encrypted)."
T["Deine Route als Text teilen oder die Route von jemand anderem laden. Eine geladene Route zeigt Namen in deiner Sprache."] = "Share your route as text or load someone else's route. A loaded route shows names in your language."
T["Im grossen Fenster unter Start auf Route exportieren und laden klicken."] = "In the main window under Start, click Export and load route."
T["Klick teilt deine Route, Rechtsklick lädt eine."] = "Click shares your route, right click loads one."
T["Wartet auf die Gruppen Route vom Leiter"] = "Waiting for the group route from the leader"
T["Klick auf einen Namen: hinlaufen und helfen"] = "Click a name: go there and help"
T["Du"] = "You"
T["hinten"] = "behind"
T["vorne"] = "ahead"
T["%s helfen"] = "Help %s"
T["Pfeil zeigt zu %s. Klick im Mini Fenster auf das Ziel bringt dich zurück auf die Route."] = "The arrow points to %s. Click the target in the mini window to get back to your route."
T["Wo %s ist, ist noch nicht bekannt. Das kommt alle 10 Sekunden."] = "%s's position isn't known yet. It updates every 10 seconds."
T[" (Leiter)"] = " (leader)"
T["Schritt %d von %d der Gruppen Route"] = "Step %d of %d of the group route"
T["Klick: der Pfeil zeigt zu ihm, damit du hinlaufen und helfen kannst."] = "Click: the arrow points to them so you can go there and help."
T["Gruppen Ansicht"] = "Group view"
T["Pro Mitspieler eine Zeile mit seinem Schritt. Klick auf einen Namen: hinlaufen und helfen."] = "One line per group member with their step. Click a name: go there and help."
T["Mini Fenster mit Gruppen Ansicht?"] = "Mini window with group view?"
T["Wie gross, dazu in der Gruppe eine Zeile pro Mitglied: bei welchem Schritt der Gruppen Route er ist (zb 7/15). Klick auf einen Namen: hinlaufen und helfen."] = "Like large, plus in a group one line per member: which step of the group route they are on (e.g. 7/15). Click a name: go there and help."
-- 17.2 Rundgang
T["Diese Seite erklären"] = "Explain this page"
T["Erklärt diese Seite Schritt für Schritt. Den ganzen Rundgang gibt es auf der Übersicht."] = "Explains this page step by step. The full tour is on the Overview."
T["Rundgang starten"] = "Start tour"
T["Rundgang fortsetzen"] = "Continue tour"
T["Schritt %d"] = "Step %d"
T["Dein Stand auf einen Blick: Level, XP, die nächsten Ziele und Pause."] = "Your progress at a glance: level, XP, the next goals and pause."
T["Pause"] = "Pause"
T["Rundgang"] = "Tour"
T["Dieser Rundgang. Er merkt sich, wo du aufgehört hast."] = "This tour. It remembers where you stopped."
T["Unten deine Ziele als Karten, zum Beispiel Dungeons und Bücher. Klick öffnet die Seite dazu."] = "Your goals as cards below, like dungeons and books. Click to open the page."
T["Welche Funktion ab welchem Level kommt. Gelb ist die nächste Stufe."] = "Which feature comes at which level. Yellow is the next stage."
T["Alle Schritte der Route, der Zonenplan bis 60 und Planen: neu rechnen, Touren, Stunden Budget, Feierabend."] = "All route steps, the zone plan to 60 and planning: recalculate, tours, Time budget, call it a day."
T["Schritt 1"] = "Step 1"
T["Schritt 2"] = "Step 2"
T["Oben die Reiter Schritte, Zonenplan und Planen."] = "At the top the tabs Steps, Zone plan and Plan."
T["Neu rechnen rechnet die Route ab deinem Standort, zum Beispiel nach einem Umweg."] = "Recalculate calculates the route from where you are, for example after a detour."
T["Im Modus Geführt stehen zuerst die wichtigsten. Dieser Knopf zeigt alle."] = "In Guided mode the most important ones come first. This button shows all of them."
T["Alles zum Nachlesen. Hier startest du auch die Einrichtung und die kurzen Erklärungen nochmal."] = "Everything to read up on. You can also restart the setup and the short explanations here."
T["Rundgang fertig"] = "Tour finished"
T["Mit dem Level kommen noch: %s. Jede neue Seite erklärt sich beim ersten Öffnen."] = "Still coming with your level: %s. Each new page explains itself the first time you open it."
T["Du kennst jetzt alle Seiten. Das ? oben rechts erklärt jede Seite nochmal."] = "You now know all pages. The ? at the top right explains each page again."
T["Reiter %d von %d, Schritt %d von %d"] = "Tab %d of %d, step %d of %d"
T["Beenden"] = "Close"
T["Nächster Reiter"] = "Next tab"
T["Für diese Seite gibt es noch keinen Rundgang."] = "There is no tour for this page yet."
T["Kommt ab Level %d. Im Modus Experte ist alles sofort da."] = "Comes at level %d. In Expert mode everything is there right away."
T["5. "] = "5. "
T[" auf der Übersicht zeigt alle Seiten Schritt für Schritt und merkt sich, wo du aufgehört hast. Das "] = " on the overview shows all pages step by step and remembers where you stopped. The "
T[" oben rechts im grossen Fenster erklärt nur die Seite, die gerade offen ist."] = " at the top right of the big window explains only the page that is open."
T["/klg experte"] = "/klg expert"
T[" Mit 60 ist alles da, fast wie bei Experte. Die Route rechnet in beiden Modi gleich."] = " At 60 everything is there, almost like Expert. The route is calculated the same in both modes."
T["Quest %s: %d Schritte aus der Route genommen%s."] = "Quest %s: %d steps taken out of the route%s."
T["abgebrochen"] = "abandoned"
T[", mit %d Folgequests"] = ", with %d follow-up quests"
T["übersprungen"] = "skipped"
T["|cffffd100%s|r: %d Schritte"] = "|cffffd100%s|r: %d steps"
T["%d Schritte, Level %d"] = "%d steps, level %d"
T["|cffff5050feindlich|r"] = "|cffff5050hostile|r"
T["Questlog voll (%d von %d): neue Quests hier lässt die Route aus. Mit Platz im Log kommen sie beim nächsten Abschnitt wieder."] = "Quest log full (%d of %d): the route skips the new quests here. With room in the log they come back in the next section."
T["  gute Quests in sinnvoller Reihenfolge. Das ist der Standard."] = "  good quests in a sensible order. This is the default."
T["/klg an"] = "/klg on"
T["/klg aus"] = "/klg off"
T["/klg erklaerungen  alle Erklärungen wieder zeigen,  /klg wege  Stand vom Wege teilen"] = "/klg explain  show all explanations again,  /klg paths  status of shared paths"
T["Für die nächsten Quests fehlt noch Level (Level %d nötig, du bist %d). Der Abschnitt wird ab hier neu gerechnet."] = "The next quests need a higher level (level %d needed, you are %d). Recalculating the section from here."
T["Für diese Quests fehlt noch Level (Level %d nötig): die Route lässt sie hier aus, sie kommen später wieder."] = "These quests need a higher level (level %d): the route skips them here, they come back later."
T["Level fehlt noch"] = "level too low"
T["%d gespeicherte Einträge waren kaputt und wurden neu angelegt."] = "%d saved entries were broken and have been reset."
T["  keine Grind Schritte, nur Quests. Nur wenn es in deinem Level gar keine Quest mehr gibt, kommt kurz der Hinweis Level fehlt."] = "  no grind steps, only quests. Only if there is no quest at all for your level, a short level missing hint appears."
T["Bücher Umweg stellst du unter Einstellungen, Bereich Tempo, ein."] = "Set the book detour under Settings, Pace."
T["Welche Quests die Route nimmt: Tempo, Grinden, Dungeon Quests, Eskorten, Kontinent, Bücher"] = "Which quests the route takes: pace, grinding, dungeon quests, escorts, continent, books"
T["Ja: Grind Stopps, wo Grinden schneller ist als die nächste Quest, höchstens 15 Minuten. Nein: nur Quests."] = "Yes: grind stops where grinding beats the next quest, at most 15 minutes. No: quests only."
T["Ja: Quests für einen Dungeon kommen mit kleinem Umweg mit, damit du sie dort dabei hast. Nein: nur ihre Vorquests."] = "Yes: quests for a dungeon are picked up with a small detour, so you have them there. No: only their prequests."
T["Ja: Quests, bei denen du jemanden begleitest oder etwas auslöst, kommen mit. Nein: sie fallen weg."] = "Yes: escort and event quests are included. No: they're skipped."
T["Ja: für gute Quests darf die Route per Schiff oder Zeppelin den Kontinent wechseln. Nein: sie bleibt hier."] = "Yes: for good quests the route may switch continents by boat or zeppelin. No: it stays here."
T["Ja: Bücher nahe der Route kommen mit, der Umweg ist einstellbar. Nein: keine Bücher, du kannst sie trotzdem gezielt holen."] = "Yes: books near the route are included, the detour can be set. No: no books, you can still get them on purpose."
T["Bei jeder Stufe steht, wie viel länger sie für dich dauert als Normal. Ändern geht jederzeit."] = "Each step shows how much longer it takes you than Normal. You can change it any time."
T["Drück auf Route berechnen, dann kannst du gleich weitermachen. Bis die Route fertig ist, kann das Spiel kurz ruckeln."] = "Press Calculate route, then you can carry on right away. Until the route is done, the game may stutter briefly."
T["|cffff5050Zuerst Route berechnen drücken, dann geht es weiter.|r"] = "|cffff5050Press Calculate route first, then you can continue.|r"
T["%s: %s"] = "%s: %s"
T[". Nach Level 60 geht die Route weiter, bis alle Quests fertig sind."] = ". After level 60 the route goes on until all quests are done."
T["In der Gruppe eine Zeile pro Mitspieler unter dem Mini Fenster, mit seinem Schritt. Klick auf einen Namen: hinlaufen und helfen."] = "In a group, one line per member below the mini window with their step. Click a name: go there and help."
T["Fenster"] = "Windows"
T["Rechnet ab hier neu, zum Beispiel nach einem Umweg. Der Plan bis 60 bleibt."] = "Recalculates from here, e.g. after a detour. The plan to 60 stays."
T["Abschnitt neu rechnen"] = "Recalculate section"
T["Plan bis 60 komplett neu"] = "Redo whole plan to 60"
T["Löscht Plan, Verlauf und Zeiten und rechnet alles neu, wie bei einem neuen Charakter. Für normale Änderungen reicht Abschnitt neu rechnen."] = "Deletes plan, history and times and recalculates everything, like a new character. For normal changes Recalculate section is enough."
T["|cffffd100Zeit pro Zone|r  |cff9d9d9dwie lange du dort warst und wie lange der Plan dort noch rechnet|r"] = "|cffffd100Time per zone|r  |cff9d9d9dhow long you were there and how long the plan still counts there|r"
T["Die Route sagt dir, in welchem Gasthaus du dich binden sollst. Dort ausloggen gibt Ruhebonus."] = "The route tells you at which inn to bind. Logging out there gives rested bonus."
T["In Meine Route kommt der Reiter Planen dazu: Questlog Route, später Stunden Budget, Flugpunkte und Entdecken Tour."] = "My Route gets the Plan tab: quest log route, later Time budget, flight point and explore tour."
T["Im grossen Fenster unter Meine Route, Reiter Planen."] = "In the main window under My Route, Plan tab."
T["Kommt ab Level %d."] = "Comes at level %d."
T["Geführt: mit jeder Stufe kommt etwas dazu. Klick auf eine freie Karte öffnet die Funktion, Maus auf eine gesperrte zeigt, was kommt."] = "Guided: each step adds something. Click an unlocked card to open it, hover a locked one to see what's coming."
T["Keine Quest ausgewählt. Links die Haken bei den Quests setzen, die du willst (Dungeon Quests laufen über die Dungeon Seite)."] = "No quest selected. Tick the quests you want on the left (dungeon quests go through the dungeon page)."
T["|cff9d9d9dNicht ausgewählt: Haken setzen, dann kommt sie mit Route berechnen in die Route.|r"] = "|cff9d9d9dNot selected: tick it, then Calculate route adds it to your route.|r"
T["/klg  grosses Fenster,  /klg hilfe  Anleitung im grossen Fenster"] = "/klg  main window,  /klg help  guide in the main window"
T["/klg einrichten  Einrichtung nochmal,  /klg gefahr | gefahrweg  Gefahr hier markieren oder löschen"] = "/klg setup  run setup again,  /klg danger | nodanger  mark or clear danger here"
T["Das Menü hat drei Bereiche:"] = "The menu has three parts:"
T[" rechnet den Abschnitt ab hier neu. Läuft eine Tour oder Farm Route, wechselst du hier zwischen ihr und der "] = " recalculates the section from here. If a tour or farm route is running, you switch here between it and the "
T[" steht nur da, solange eine Farm Route läuft."] = " only shows while a farm route is running."
T[" (Pfeil zum nächsten Händler), "] = " (arrow to the nearest vendor), "
T[" (Pfeil zum nächsten Gasthaus, mit Abgaben auf dem Weg), "] = " (arrow to the nearest inn, with turn ins on the way), "
T[" (Quest Items zum Kaufen) und "] = " (quest items to buy) and "
T[" (Leveln, Dungeons, Ausrüstung, Bücher oder Ruf)."] = " (leveling, dungeons, gear, books or reputation)."
T[" öffnet das grosse Fenster, "] = " opens the main window, "
T[" schaltet die Zeilen der Mitspieler unter dem Mini Fenster an oder aus."] = " turns the party member lines under the mini window on or off."
T["Einen Schritt auslassen: einfach "] = "To skip a step: just press "
T[" drücken."] = "."
T["Ein Regler mit zwei Stufen und ein paar Fragen mit Ja und Nein. Alles davon steht in den Einstellungen im Bereich "] = "A slider with two levels and a few yes or no questions. All of it is in Settings under "
T["  alle machbaren Quests, auch solche, die kaum noch XP geben. Zonen werden fertig gemacht, bevor es weiter geht. Nach Level 60 geht die Route weiter, bis alle Quests fertig sind."] = "  every doable quest, even ones that give little XP. Zones get finished before moving on. After level 60 the route keeps going until all quests are done."
T["Eskorten einplanen"] = "Plan escort quests"
T["  Nein: Eskort Quests kommen nicht in die Route."] = "  No: escort quests stay out of the route."
T["  Nein: die Route bleibt auf deinem Kontinent, solange es dort genug Quests gibt."] = "  No: the route stays on your continent as long as there are enough quests there."
T["Bibliotheksbücher am Weg mitnehmen"] = "Pick up library books on the way"
T["  Ja: ein Buch kommt in die Route, wenn es nur einen kleinen Umweg kostet. Wie gross der Umweg sein darf, stellst du gleich darunter ein."] = "  Yes: a book goes into the route if it is only a small detour. How big the detour may be is set right below."
T["Bei jeder Stufe steht, wie viel schneller oder langsamer sie für dich ist als Normal, zum Beispiel "] = "Each level shows how much faster or slower it is for you than Normal, for example "
T["20% langsamer"] = "20% slower"
T[". Die Zahl kommt aus deinen gemessenen Zeiten (Lauftempo, Kampf, Pausen). Am Anfang steht "] = ". The number comes from your measured times (run speed, combat, breaks). At first it says "
T[". Das rechnet nur den Abschnitt ab hier neu, der Plan bis 60 bleibt."] = ". This only recalculates the section from here, the plan to 60 stays."
T["Im Zonenplan gibt es dazu "] = "The zone plan also has "
T[": das rechnet alle Zonen und Level bis 60 von vorne. Das brauchst du nur, wenn der Plan gar nicht mehr passt."] = ": this recalculates all zones and levels to 60 from scratch. You only need it if the plan no longer fits at all."
T["Den Reiter "] = "The tab "
T[" gibt es bei Geführt ab Level 13 (steht auch in "] = " comes at level 13 in Guided (also shown in "
