T["Alle Stufen bis 60 als Karten, mit einer Linie verbunden. Klick auf eine freie Karte springt zur Funktion. Eine gesperrte Karte kannst du nicht anklicken, Maus drauf zeigt, ab welchem Level sie kommt. Die Erklärung kommt, sobald du das Level erreichst."] = "All steps to 60 as cards, joined by a line. Click an unlocked card to jump to the feature. A locked card can't be clicked, hover shows the level it comes at. The explanation shows once you reach that level."
T["Statistik|r"] = "Stats|r"
T["Deine gemessenen Zeiten: XP pro Stunde, Kampf, Laufen, Pausen und "] = "Your measured times: XP per hour, combat, running, breaks and "
T[" (geplant gegen echt)."] = " (planned vs real)."
T["Dungeons|r"] = "Dungeons|r"
T["Ein Buch ist auf der normalen Route einen kleinen Umweg wert (Standard 600 Yards, einstellbar unter Einstellungen, Tempo)."] = "A book is worth a small detour on the normal route (default 600 yards, set in Settings, Pace)."
T["Gold|r"] = "Gold|r"
T[" unter dem Mini Fenster zeigt pro Mitglied eine Zeile, bei welchem Schritt es ist. Standard ist an, aus im Menü vom Mini Fenster oder in den Einstellungen."] = " under the mini window shows one line per member with the step they are on. On by default, turn it off in the mini window menu or in Settings."
T["  Alles oder Normal, dazu was die Route mitnimmt: Grinden, Dungeon Quests, Eskorten, Kontinent wechseln und Bücher mit Umweg."] = "  All or Normal, plus what the route takes along: grinding, dungeon quests, escorts, continent switch and books with detour."
T["  Flüge, Ruhestein, Taschen (Händler einplanen), Reittier, Wege teilen."] = "  Flights, Hearthstone, bags (plan vendors), mount, share paths."
T["Fast alles geht über die Knöpfe im Mini Fenster und im grossen Fenster. Die Befehle hier sind für Makros oder wenn ein Fenster weg ist.|r"] = "Almost everything works with the buttons in the mini window and the main window. These commands are for macros or when a window is gone.|r"
