T["  Einrichtung nochmal."] = "  run setup again."
T["/klg gefahr"] = "/klg danger"
T["/klg gefahrweg"] = "/klg nodanger"
T["  wieder löschen. Geht auch mit Alt+Klick auf der Karte."] = "  clear it again. Alt+Click on the map works too."
