T["/klg gefuehrt"] = "/klg guided"
T["/klg wege"] = "/klg paths"
T["Sprich %s an (Rechtsklick). Brauchst du nichts, geht es mit Weiter oder in 45 Sekunden von selbst weiter."] = "Talk to %s (right click). If you need nothing, press Next or the route moves on by itself in 45 seconds."
