T["Wie schnell deine Figur in Mein Weg läuft: normal oder doppelt so schnell. Nur die Anzeige, die Route bleibt gleich."] = "How fast your figure walks in My Way: normal or twice as fast. Display only, the route stays the same."
T["Dein Charakter läuft den ganzen Weg nochmal ab, in der Ausrüstung von damals (alle 5 Level)."] = "Your character walks the whole path again, in the gear you wore back then (every 5 levels)."
