T["Deine Position ist gerade nicht bekannt."] = "Your position is not known right now."
T["Dorthin findet das Navi keinen Weg (anderer Kontinent ohne bekannte Verbindung)."] = "The navi finds no way there (other continent without a known connection)."
T["Flug nach %s"] = "Flight to %s"
T["Flüge: %d selbst gemessen, %d von anderen bekommen"] = "Flights: %d measured yourself, %d received from others"
T["Für diese Stelle kennt das Addon keine Weltposition."] = "The addon knows no world position for this spot."
T["Klick hier, dann auf der Karte auf dein Ziel. Das Navi sucht den schnellsten Weg mit Reittier, Flugpunkten, Schiff, Zeppelin und Ruhestein, der Pfeil führt dich hin. Nochmal klicken beendet es."] = "Click here, then click your destination on the map. The navi finds the fastest way with mount, flight points, boat, zeppelin and hearthstone, the arrow leads you there. Click again to end it."
T["Navi"] = "Navi"
T["Navi beendet, Pfeil wieder auf der Route."] = "Navi ended, arrow back on the route."
T["Navi nach %s: ca %s"] = "Navi to %s: about %s"
T["Navi: "] = "Navi: "
T["Navi: Ziel erreicht, weiter mit der Route."] = "Navi: destination reached, back to the route."
T["Navi: hier ist keine Zone, bitte auf eine Zone klicken."] = "Navi: no zone here, please click on a zone."
T["Navi: jetzt auf der Karte auf dein Ziel klicken."] = "Navi: now click your destination on the map."
T["Navi: neuer Weg ab hier"] = "Navi: new way from here"
T["Ruhestein benutzen (%s)"] = "Use hearthstone (%s)"
T["Zum %s nach %s"] = "To the %s to %s"
T["Zum Flugmeister %s"] = "To flight master %s"
T["Zum Ziel"] = "To the destination"
T["Navi|r"] = "Navi|r"
T["Knopf Navi an der Karte, dann Klick auf dein Ziel. Das Navi sucht den schnellsten Weg: laufen oder reiten mit deinem Tempo, Flugpunkte die du kennst, Schiff und Zeppelin (mit Nauticus die echte Abfahrt) und den Ruhestein, wenn er bereit ist. Im Chat stehen die Abschnitte mit Zeit, auf der Karte die Strecke, der Pfeil führt Abschnitt für Abschnitt."] = "Navi button on the map, then click your destination. The navi finds the fastest way: walking or riding at your speed, flight points you know, boat and zeppelin (with Nauticus the real departure) and the hearthstone when it is ready. The chat lists the legs with times, the map shows the way, the arrow leads leg by leg."
T["Am Ziel geht es von selbst zurück zur Route. Abbrechen: nochmal auf Navi oder auf die Ziel Zeile im Mini Fenster klicken."] = "At the destination it goes back to the route by itself. To cancel: click Navi again or the target line in the mini window."
T["Flugzeiten"] = "Flight times"
T["  Jeder Flug wird gemessen und gemerkt, Navi und Route rechnen dann mit der echten Zeit. Mit "] = "  Every flight is measured and remembered, navi and route then use the real time. With "
T[" gehen deine Flugzeiten auch an andere Spieler und ihre zu dir. "] = " your flight times also go to other players and theirs to you. "
T["/klg fluege"] = "/klg flights"
T[" zeigt, wie viele es sind."] = " shows how many there are."
T["Dein Charakter läuft als kleine Figur den Weg entlang bis zu deinem Level, mit der Ausrüstung, die du trägst. Alle 5 Level merkt sich das Addon, was du anhast. "] = "Your character walks the path as a small figure up to your level, wearing your gear. Every 5 levels the addon remembers what you wear. "
T[" auf der Karte Level 60 lässt ihn den ganzen Weg nochmal ablaufen, mit der Ausrüstung von damals."] = " on the level 60 card lets him walk the whole path again, with the gear from back then."
T["Schlafsack bereit: beim nächsten Essen oder Trinken hinlegen"] = "Sleeping bag ready: lie down at your next eat or drink break"
T["3 Minuten liegen gibt bis +3 % XP. Essen und Trinken geht dabei weiter, kostet also keine Zeit. X: eine Stunde Ruhe."] = "Lying down 3 minutes gives up to +3 % XP. You can keep eating and drinking, so it costs no time. X: quiet for an hour."
T["Schlafsack aus der Tasche benutzen und 3 Minuten liegen bleiben (1 Stapel pro Minute)."] = "Use the sleeping bag from your bags and stay lying down for 3 minutes (1 stack per minute)."
T["   oder statt Gasthaus: Schlafsack hinlegen und darin ausloggen"] = "   or instead of the inn: put down the sleeping bag and log out in it"
T["Du kannst dich auch in den Schlafsack legen und darin ausloggen (wieder bereit in %s)."] = "You can also lie down in the sleeping bag and log out in it (ready again in %s)."
T["Du kannst dich auch gleich hier in den Schlafsack legen und darin ausloggen, das zählt auch als Ruhezone."] = "You can also lie down in the sleeping bag right here and log out in it, it counts as a rest area too."
T["Navi ausgeblendet, Pfeil auf der Route. Im Menü unter Route kommt es wieder."] = "Navi hidden, the arrow follows the route. It comes back in the menu under Route."
