T["Die Gegner hier sind noch zu hoch (Level %d): die Route lässt diese Quests hier aus, sie kommen später wieder."] = "The enemies here are still too high (level %d): the route skips these quests here, they come back later."
T["Die Elite Gegner hier (Level %d) sind allein noch zu stark, du bist %d. Der Abschnitt wird ab hier neu gerechnet."] = "The elite enemies here (level %d) are still too strong to do alone, you are %d. The section is recalculated from here."
T["Die Elite Gegner hier (Level %d) sind allein noch zu stark: die Route lässt diese Quests hier aus, sie kommen später wieder."] = "The elite enemies here (level %d) are still too strong to do alone: the route skips these quests here, they come back later."
