T["Navi: Das Ziel ist zu Fuss nicht erreichbar (%s). Der Pfeil führt so nah wie möglich hin, dann fehlen noch ca %d yd."] = "Navi: the target can't be reached on foot (%s). The arrow leads as close as possible, then about %d yd remain."
