T["Diese Quests braucht die Route nicht oder noch nicht. Quests mit Haken werden abgebrochen, das geht nicht rückgängig. Ohne Haken bleibt die Quest."] = "The route doesn't need these quests, or not yet. Checked quests get abandoned, this can't be undone. Unchecked quests stay."
T["Gelände Daten fehlen: im Ordner KeineZeitLevelingGuide fehlt der Unterordner Karte. Der Pfeil zeigt dann die Luftlinie und deine gelaufenen Wege."] = "Terrain data missing: the folder ForeverWegweiser has no Karte subfolder. The arrow then shows the straight line and the paths you walked."
T["Die Karten sind jetzt im Addon. Den Ordner %s in Interface\\AddOns kannst du löschen."] = "The maps are now part of the addon. You can delete the folder %s in Interface\\AddOns."
