T["|cff4dccffNavi aktiv|r  |cff9d9d9d(Klick: ausblenden, zurück zur Route)|r"] = "|cff4dccffNavi active|r  |cff9d9d9d(Click: hide, back to the route)|r"
T["Wegpunkt %d"] = "Waypoint %d"
T["Laufen ist in Wegpunkte entlang der Wege geteilt: Wegpunkt 1, Wegpunkt 2, dann Flugmeister oder Zeppelin. Das Mini Fenster zeigt den Navi Schritt wie einen Routen Schritt."] = "Walking is split into waypoints along the roads: waypoint 1, waypoint 2, then flight master or zeppelin. The mini window shows the navi step like a route step."
T["Das Navi ist ein eigenes Profil wie die Tour: im Mini Fenster Menü unter Route wechselst du zwischen Leveling Route und Navi, das Navi bleibt dabei gemerkt (auch nach Neuladen). Navi beenden wirft es weg. Am Ziel geht es von selbst zurück zur Route."] = "The navi is its own profile like the tour: in the mini window menu under Route you switch between Leveling Route and Navi, the navi stays remembered (even after a reload). End navi throws it away. At the destination it goes back to the route by itself."
T["Rechts an der Karte sind die Knöpfe von Forever Wegweiser. Das Logo oder Plus und Minus klappt die Leiste auf und zu."] = "The Forever Wegweiser buttons are on the right of the map. The logo or plus and minus folds the bar in and out."
T["Pause ist noch an, nichts wird gerechnet. Weiter: Mini Fenster Menü, Weitermachen, oder /klg pause."] = "Still paused, nothing is calculated. Resume: mini window menu, Resume, or /klg pause."
T["Im Dungeon rechnet die Route nicht, dort gibt es keine Position. Draussen geht es von selbst weiter."] = "In a dungeon the route does not calculate, there is no position there. Outside it continues by itself."
T["Im Dungeon kennt das Spiel deine Position nicht. Draussen nochmal das Ziel wählen."] = "In a dungeon the game does not know your position. Pick the destination again outside."
T["Tiefenbahn"] = "Deeprun Tram"
T["Sturmwind"] = "Stormwind"
T["Eisenschmiede"] = "Ironforge"
