T["%sTiefenbahn:|r mit der Rattenfängerflöte 5 Ratten fangen |cff9d9d9d(sie laufen an den Gleisen beim Bahnsteig Eisenschmiede, Flöte benutzen, dann laufen sie dir nach)|r"] = "%sDeeprun Tram:|r catch 5 rats with the Rat Catcher's Flute |cff9d9d9d(they run along the tracks near the Ironforge platform, use the flute and they follow you)|r"
T["%sTiefenbahn:|r %s bei Monty abgeben |cff9d9d9d(Bahnsteig Eisenschmiede, die Flöte gibst du dabei zurück)|r"] = "%sDeeprun Tram:|r turn in %s to Monty |cff9d9d9d(Ironforge platform, you hand the flute back)|r"
T["Tiefenbahn: Quest bei Monty annehmen\n|cff9d9d9dBahnsteig Eisenschmiede, ohne Pfeil|r"] = "Deeprun Tram: accept quest from Monty\n|cff9d9d9dIronforge platform, no arrow here|r"
