T["Verbindung: Tunnel, Brücke"] = "Link: tunnel, bridge"
T["Grenze zu (kein Durchgang)"] = "Border closed (no passage)"
T["Klick setzt Wegpunkte, dazwischen wird Weg gemalt (Pinsel Grösse zählt). Rechtsklick beendet den Weg."] = "Click sets waypoints, the path between them gets painted (brush size counts). Right click ends the path."
T["Klick an einem Durchgang nahe der Zonengrenze. Rechtsklick löscht Übergänge in der Nähe."] = "Click on a passage near the zone border. Right click removes crossings nearby."
T["Klick auf den Anfang, dann auf das Ende (auch in der Nachbarzone). Rechtsklick bricht ab oder löscht."] = "Click the start, then the end (also in the next zone). Right click cancels or removes."
T["Klick nahe der Grenze: zwischen den zwei Zonen gibt es nur gemalte und gelaufene Übergänge. Rechtsklick öffnet."] = "Click near the border: between these two zones only painted and walked crossings count. Right click opens it."
