T["Verbindung: das Ende ist zu nah am Anfang oder auf einem anderen Kontinent."] = "Link: the end is too close to the start or on another continent."
T["Verbindung gesetzt: %s nach %s, %d Yards."] = "Link set: %s to %s, %d yards."
T["%d Übergänge gelöscht."] = "%d crossings removed."
T["%d geschlossene Grenzen geöffnet."] = "%d closed borders opened."
T["Keine Nachbarzone in 300 Yards: näher an die Zonengrenze klicken."] = "No neighbouring zone within 300 yards: click closer to the zone border."
T["Übergang gesetzt: %s und %s (an der Grenze, %d Yards vom Klick)."] = "Crossing set: %s and %s (on the border, %d yards from the click)."
T["Grenze zu: %s und %s. Dort zählen jetzt nur gemalte und gelaufene Übergänge."] = "Border closed: %s and %s. Only painted and walked crossings count there now."
