T["Export: alles ist markiert, mit Strg+C kopieren"] = "Export: everything is selected, copy with Ctrl+C"
T["Export: %d Zeichen."] = "Export: %d characters."
T["gemalt"] = "painted"
T["mitgeliefert"] = "shipped"
