T["Prio 2: nur starker PC"] = "Priority 2: strong PC only"
T["Prio für neue Punkte"] = "Priority for new points"
T["Prio 1: wenige wichtige Punkte, gelten immer. Prio 2: zusätzliche Punkte, nur ohne \"schwacher PC\" (genauer, aber mehr Rechnen)."] = "Priority 1: a few important points, always used. Priority 2: extra points, only without \"weak PC\" (more accurate, but more calculation)."
-- 18.3 Konflikt Hinweis Auto Quest
T["|cffffd100%s ist auch an.|r Zusammen mit Auto Quest vom Forever Wegweiser klicken beide, und das schnellere wählt die Belohnung. Tipp: nur eins davon an lassen."] = "|cffffd100%s is also enabled.|r Together with Auto Quest from Forever Wegweiser both click, and the faster one picks the reward. Tip: keep only one of them on."

