-- 19.0 Werkzeug Karte
T["Gelände Daten fehlen: das Addon KeineZeitLevelingGuide_Karte_Forever (WoW Forever) oder KeineZeitLevelingGuide_Karte_Era (Classic Era) ist nicht geladen. Der Pfeil zeigt dann die Luftlinie und deine gelaufenen Wege."] = "Terrain data missing: the addon KeineZeitLevelingGuide_Karte_Forever (WoW Forever) or KeineZeitLevelingGuide_Karte_Era (Classic Era) is not loaded. The arrow then shows the straight line and the paths you walked."
T["Gelände Daten passen nicht zu diesem Client. Bitte Keine Zeit Leveling Guide neu installieren."] = "Terrain data does not match this client. Please reinstall Keine Zeit Leveling Guide."
T["Wege um Berge?"] = "Paths around mountains?"
T["Pfeil und Karte folgen bekannten Wegen statt quer über den Berg."] = "Arrow and map follow known paths instead of straight over the mountain."
T["Pfeil: sicherer Weg?"] = "Arrow: safe path?"
T["Der Pfeil geht um Mobs herum, die für dich nicht grau sind, wenn der Weg höchstens 20 % länger ist."] = "The arrow goes around mobs that aren't gray for you, if the path is at most 20 % longer."
-- 19.27 Sprungstellen (k4)
T["Pfeil: runter springen?"] = "Arrow: jump down?"
