T["Daten Stand: Build %s, dein Spiel Build %s. Nach einem Patch kann die Karte an einzelnen Stellen veraltet sein."] = "Data version: build %s, your game build %s. After a patch the map can be outdated in some places."
T[", Daten %s"] = ", data %s"
T[", Korrektur %s"] = ", corrections %s"
T["Elite Grenze lernt mit?"] = "Elite limit learns?"
T["Stirbst du oft, kommen Elite Gegner allein erst später. Lange ohne Tod wieder früher, bis 1 Level Abstand."] = "If you die often, solo elite enemies come later. After a long time without dying, earlier again, down to a 1 level gap."
T["Elite allein ab %d Level unter dir"] = "Elite solo from %d levels below you"
T["früher"] = "earlier"
T["später"] = "later"
T["Pfeil und Mini Fenster aus"] = "Arrow and mini window off"
T["Pfeil und Mini Fenster an"] = "Arrow and mini window on"
T["Wo fängst du an?"] = "Where do you start?"
T["mehr"] = "more"
T["Mehr Schritte"] = "More steps"
T["Zeigt die nächsten 5 Schritte unter dem jetzigen. Nochmal klicken: nur noch der nächste."] = "Shows the next 5 steps below the current one. Click again: only the next one."
T["weniger"] = "fewer"
T["Mini Fenster zeigt %d nächste Schritte"] = "Mini window shows %d next steps"
T["Nächste Schritte im Mini Fenster"] = "Next steps in the mini window"
T["1, 3, 5 oder 8 Zeilen unter dem jetzigen Schritt. Nur im grossen Mini Fenster."] = "1, 3, 5 or 8 lines under the current step. Large mini window only."
T["Jetzt: %s. Woanders anfangen geht hier oder später im grossen Fenster."] = "Now: %s. To start elsewhere, use this or the main window later."
T["Woanders anfangen geht hier oder später im grossen Fenster."] = "To start elsewhere, use this or the main window later."
T["Pfeil und Mini Fenster weg, nichts rechnet mehr. Nochmal klicken holt beides zurück."] = "Hides arrow and mini window, nothing is calculated. Click again to bring them back."
T["Gelände Daten sind neuer als dieses Addon (Format %d, das Addon kennt bis %d). Der Pfeil nimmt bis zum Update die Luftlinie und deine gelaufenen Wege."] = "Terrain data is newer than this addon (format %d, the addon knows up to %d). Until you update, the arrow uses the straight line and the paths you walked."
T["Gelände Karte: keine Daten."] = "Terrain map: no data."
T["Gelände Karte: %s, Stand %s, Build %s, %d Zonen, %d geladen, %d mit Netz%s."] = "Terrain map: %s, version %s, build %s, %d zones, %d loaded, %d with path network%s."
T[", rechnet noch"] = ", still calculating"
T["Zonen Wege: "] = "Zone paths: "
T["Zum Ziel: Luftlinie %s yd, über das Wegnetz %s yd."] = "To the target: straight line %s yd, via the path network %s yd."
T["(Luftlinie ist frei)"] = "(straight line is clear)"
T["|cffffd100Testmodus:|r /klg karte  Stand der Gelände Karte und Strecke zum Ziel über das Wegnetz"] = "|cffffd100Test mode:|r /klg terrain  terrain map status and distance to the target via the path network"
T["Die Gelände Karte (im Addon, Ordner Karte) kennt Berge, Wasser, Klippen, Wege und die Übergänge zwischen den Zonen. Damit rechnet die Route die echten Laufwege, und der Pfeil führt Stück für Stück um das Gelände, auch über mehrere Zonen. Dazu lernt Forever Wegweiser, wo du schon gelaufen bist: dort ist nie ein Berg. "] = "The terrain map (inside the addon, folder Karte) knows mountains, water, cliffs, paths and the crossings between zones. With it the route calculates the real walking paths, and the arrow leads step by step around the terrain, also across several zones. On top Forever Wegweiser learns where you have walked: there is never a mountain there. "
T["/klg karte"] = "/klg terrain"
T["Ist die Gelände Karte geladen ("] = "Is the terrain map loaded ("
T[")? Ohne sie kennt Forever Wegweiser nur die Wege, die du gelaufen bist. Lauf einmal den richtigen Weg, dann lernt er ihn. Oder setze mit Alt+Klick auf der Karte eine Gefahr."] = ")? Without it Forever Wegweiser only knows the paths you walked. Walk the right path once, then it learns it. Or set a danger with Alt+Click on the map."
T["Übergänge gegen die Karten des Clients: im Mittel %d yd, höchstens %d yd daneben."] = "Crossings against the client maps: on average %d yd, at most %d yd off."
-- 19.10 Tempo Alles: Variante Rest auf 60
T["Alles: graue Quests abseits erst auf 60?"] = "All: grey quests off the path only at 60?"
T["Nur bei Tempo Alles. Ja: graue Quests weit weg kommen erst auf 60, alles am Weg kommt mit. Nein: jede Quest von Anfang an, der lange Weg bis 60."] = "Only with pace All. Yes: gray quests far away come at 60, everything on the way comes along. No: every quest from the start, the long way to 60."
T["grau und abseits, kommt auf Max Level"] = "grey and off the path, comes at max level"
T["Einrichtung geschlossen: die Route nimmt die Standard Einstellungen. Ändern geht im grossen Fenster unter Einstellungen oder mit /klg einrichten."] = "Setup closed: the route uses the default settings. Change them in the main window under Settings or with /klg setup."
-- 19.32 Navi Chat Stand 4b
T["Astralen Rückruf wirken (%s)"] = "Cast Astral Recall (%s)"
T["Navi: neuer Weg mit deinen Flugpunkten, ca %s"] = "Navi: new route with your flight points, about %s"
T["Navi: Teleport"] = "Navi: teleport"
T["Teleport nach %s"] = "Teleport to %s"
T["Mit Flug ca %s schneller, Flugpunkte unbekannt"] = "About %s faster by flight, flight points unknown"
T["Navi: Mit Flug wäre es ca %s schneller, aber das Addon kennt deine Flugpunkte noch nicht. Öffne einmal bei einem Flugmeister die Flugkarte, dann rechnet das Navi mit deinen Flügen neu."] = "Navi: About %s faster by flight, but the addon does not know your flight points yet. Open the flight map once at any flight master and the Navi recalculates with your flights."
T["Navi: Mit Flug wäre es ca %s schneller, dafür fehlt der Flugpunkt %s. Kennst du ihn schon, öffne einmal die Flugkarte, dann rechnet das Navi neu."] = "Navi: About %s faster by flight, but flight point %s is missing. If you already know it, open the flight map once and the Navi recalculates."
T["Klick hier, dann auf der Karte dein Ziel. Der Pfeil nimmt den schnellsten Weg, auch mit Flug, Schiff, Ruhestein und Teleport. Nochmal klicken beendet es."] = "Click here, then your destination on the map. The arrow takes the fastest way, flights, boats, hearthstone and teleport included. Click again to end it."
T["%d yd Luftlinie\nca %s bei %d%% Tempo\n|cff9d9d9dAlt+Klick: Gefahr markieren|r"] = "%d yd straight line\nabout %s at %d%% speed\n|cff9d9d9dAlt+click: mark danger|r"
T["Navi: Teleport benutzen?"] = "Navi: use teleport?"
T["Magier: das Navi teleportiert dich in eine Hauptstadt, wenn es mindestens 1:30 Min spart (braucht eine Rune der Teleportation)."] = "Mage: the Navi teleports you to a capital when it saves at least 1:30 min (needs a Rune of Teleportation)."
T["Öffne einmal die Flugkarte bei einem Flugmeister, dann kennt der Wegweiser alle deine Flugpunkte."] = "Open the flight map once at any flight master, then the Wegweiser knows all your flight points."
-- 19.37: Modus "Experte" heisst jetzt "Alles frei" (Saschas Entscheid zwei Modi Gefuehrt / Alles frei)
T["Im Modus Alles frei ist alles sofort da."] = "In All unlocked mode everything is there right away."
T["Im Modus Geführt ab Level 35, im Modus Alles frei sofort."] = "In Guided mode from level 35, in All unlocked mode right away."
T["Noch %d Level. Im Modus Alles frei ist alles sofort da."] = "%d more levels. In All unlocked mode everything is there right away."
T["Alles frei: alle Funktionen sind da. Klick auf eine Karte springt zur Funktion."] = "All unlocked: all features are there. Click a card to jump to the feature."
T["Gold Quests und Preise (ab 35, bei Alles frei sofort)"] = "Gold quests and prices (from 35, right away in All unlocked mode)"
T["Alles frei"] = "All unlocked"
T["Alles frei: alle Seiten und Einstellungen sofort."] = "All unlocked: all pages and settings right away."
T["Alles frei: alles ist schon da"] = "All unlocked: everything is already there"
T["Modus Alles frei: alles ist sofort da."] = "All unlocked mode: everything is there right away."
T["Kommt ab Level %d. Im Modus Alles frei ist alles sofort da."] = "Comes at level %d. In All unlocked mode everything is there right away."
T["Geführt und Alles frei|r"] = "Guided and All unlocked|r"
T[" Mit 60 ist alles da, fast wie bei Alles frei. Die Route rechnet in beiden Modi gleich."] = " At 60 everything is there, almost like All unlocked. The route is calculated the same in both modes."
T["), bei Alles frei sofort. Dort sind der Tempo Regler und die Touren:"] = "), in All unlocked right away. It has the pace slider and the tours:"
T["  bei Alles frei sofort, bei Geführt ab Level 25. Eine geladene Route zeigt Namen in deiner Sprache."] = "  right away in All unlocked, from level 25 in Guided. A loaded route shows names in your language."
T["  Geführt oder Alles frei."] = "  Guided or All unlocked."
T["Bei Geführt kommen Funktionen mit dem Level. Mein Weg zeigt, wann. Im Modus Alles frei ist alles sofort da."] = "In Guided, features come as you level. My Path shows when. In All unlocked mode everything is there right away."
T["Standard: ein Buch darf bis 600 Yards Umweg sein. Im Modus Alles frei stellst du das unter Einstellungen selbst ein."] = "Default: a book can be a detour of up to 600 yards. In All unlocked mode you set this yourself under Settings."
-- 19.39: Stadt Pfeil (Arrow.lua, Navi)
T["\n|cff9d9d9dStadt: Richtung Ziel|r"] = "\n|cff9d9d9dCity: towards target|r"
-- 20.0: Ruhestein im Navi (Navi.lua, Navi Stand 8)
T["Navi: Wo dein Ruhestein gebunden ist (%s), weiss der Wegweiser noch nicht, darum plant das Navi ihn nicht ein. Einmal benutzen oder beim Gastwirt dort vorbeigehen, dann ist er bekannt."] = "Navi: The addon does not know yet where your hearthstone is bound (%s), so the navi does not use it. Use it once or walk by the innkeeper there and it will be known."
-- 20.1: Profile, Einrichtung, Mini Fenster Weniger Schritte, Tempo Normal (P1, P6, P7)
T["Die Leveling Route ist noch nicht berechnet: im Mini Fenster Menü auf Neu rechnen."] = "The leveling route is not calculated yet: in the mini window menu click Recalculate."
T["Du hast in der Einrichtung etwas geändert. Route neu berechnen? Das Spiel kann kurz ruckeln. Sonst läuft die alte Route weiter."] = "You changed something in the setup. Recalculate the route? The game may stutter briefly. Otherwise the old route continues."
T["Weniger Schritte"] = "Fewer steps"
T["Mehr: die nächsten 5 Schritte unter dem jetzigen. Weniger: wieder nur der nächste."] = "More: the next 5 steps below the current one. Fewer: only the next one again."
T["Normal ist der Standard, die anderen Stufen sind damit verglichen."] = "Normal is the default, the other levels are compared to it."
-- 20.1b: erster Abschnitt sofort, grosses Fenster nach der Einrichtung (P9, P13)
T["Weitere Level werden im Hintergrund berechnet ..."] = "More levels are being calculated in the background ..."
T["Abschnitt 1 (weitere werden berechnet)"] = "Section 1 (more are being calculated)"
T["Das ist das grosse Fenster. Später öffnest du es mit der Taste C (Reiter Forever Wegweiser im Charakterfenster), mit /klg oder im Mini Fenster unter Menü, Grosses Fenster."] = "This is the big window. Later you open it with the C key (Forever Wegweiser tab in the character window), with /klg or in the mini window under Menu, Big window."
-- 20.1c: Markieren ueber NPC Nummer, Raid Symbole als Zusatz, Abgeben ohne Quest im Log
T["Raid Symbole beim Markieren"] = "Raid icons when marking"
T["Raid Symbole beim Markieren von Blizzard gesperrt"] = "Raid icons for marking blocked by Blizzard"
T["Die eigenen Marker über Quest Mobs und Questgeber laufen weiter. Die Raid Symbole sind aus, wieder an unter Einstellungen, Quests."] = "The addon's own markers over quest mobs and quest givers keep working. Raid icons are off, turn them back on under Settings, Quests."
T["Dazu Raid Symbole setzen (Totenkopf, Stern)?"] = "Also set raid icons (skull, star)?"
T["Nur allein und ausserhalb vom Kampf. Die eigenen Marker über Quest Mobs und Questgeber kommen immer, auch ohne Raid Symbole."] = "Only when solo and out of combat. The addon's own markers over quest mobs and quest givers always show, also without raid icons."
T["Die Quest %s startet über %s in deiner Tasche: einmal anklicken, dann geht es weiter."] = "The quest %s starts from %s in your bags: click it once, then the route continues."
T["einen Gegenstand"] = "an item"
-- 20.2: Farm Runde, Texte
T["Gold farmen: %s"] = "Gold farming: %s"
T["Ruf farmen: %s"] = "Reputation farming: %s"
T["Runde %d: wieder von vorne, die Mobs sind inzwischen nachgewachsen."] = "Round %d: starting over, the mobs have respawned by now."
-- 20.2b: grosses Fenster ziehen (P15)
T["Fenster grösser oder kleiner"] = "Make the window bigger or smaller"
T["Ziehen ändert die Grösse (70 bis 160 %%, jetzt %d %%). Doppelklick: zurück auf 100 %%."] = "Drag to change the size (70 to 160 %%, now %d %%). Double click: back to 100 %%."
-- 20.2b: Schriftgroesse (P12)
T["Schriftgrösse: %d%%"] = "Font size: %d%%"
T["Schriftgrösse"] = "Font size"
T["Alle Texte von Forever Wegweiser grösser oder kleiner (80 bis 150 %), zb wenn man schlecht sieht. Das grosse Fenster kannst du zusätzlich unten rechts am Griff grösser ziehen."] = "All Forever Wegweiser texts bigger or smaller (80 to 150 %), for example if you see poorly. You can also drag the big window larger at the grip in the bottom right corner."
-- 20.3h: neuer Name (S 18:32). Alte Schluessel bleiben fuer Texte, die noch den alten Namen haben
T["   Angeln: Open World führt zu einer Stelle, die Keine Zeit Leveling Guide kennt, sonst ins Gebiet mit dem Hinweis, eine Stelle am Wasser zu suchen. Schwärme brauchen GatherMate2."] = "   Fishing: Open World leads to a spot Keine Zeit Leveling Guide knows, otherwise into the zone with a hint to find a spot by the water. Fish schools need GatherMate2."
T["   Gebiete anhaken: die Route bleibt nur dort. Nichts angehakt: Keine Zeit Leveling Guide sucht die besten Gebiete selber."] = "   Check zones: the route stays only there. Nothing checked: Keine Zeit Leveling Guide finds the best zones itself."
T["   Kräuter und Erz kommen aus GatherMate2 oder den eingebauten Gebietslisten. Keine Zeit Leveling Guide lernt selber dazu: Kräuter, Erz, Angelstellen,"] = "   Herbs and ore come from GatherMate2 or the built-in zone lists. Keine Zeit Leveling Guide also learns by itself: herbs, ore, fishing spots,"
T["   Rechtsklick auf den Keine Zeit Leveling Guide Text sperrt den Pfeil oder gibt ihn frei. Frei: am Text oder am Pfeil ziehen verschiebt beides."] = "   Right click on the Keine Zeit Leveling Guide text locks or unlocks the arrow. Unlocked: dragging the text or the arrow moves both."
T["   Tötest du so einen Mob, lernt Keine Zeit Leveling Guide Ruf pro Kill, wie viele Kills bis zur nächsten Stufe fehlen und wo es die meisten gibt."] = "   When you kill such a mob, Keine Zeit Leveling Guide learns reputation per kill, how many kills you need for the next standing and where most of them are."
T["   |cff9d9d9dNoch nichts gelernt. Töte einen dieser Mobs, dann weiss Keine Zeit Leveling Guide Ruf pro Kill und wo es die meisten gibt.|r"] = "   |cff9d9d9dNothing learned yet. Kill one of these mobs, then Keine Zeit Leveling Guide knows the rep per kill and where most of them are.|r"
T["  Questie hat noch keine Daten geliefert. Keine Zeit Leveling Guide rechnet gleich nochmal."] = "  Questie hasn't delivered any data yet. Keine Zeit Leveling Guide will calculate again shortly."
T[" (Menge lernt Keine Zeit Leveling Guide beim ersten Kill)"] = " (Keine Zeit Leveling Guide learns the amount on the first kill)"
T["3|r  Questlog fast voll? Keine Zeit Leveling Guide warnt dich vorher."] = "3|r  Quest log almost full? Keine Zeit Leveling Guide warns you before it happens."
T["Alle Questgeber, Ziele und Abgaben auf der Karte. Keine Zeit Leveling Guide baut daraus die Route."] = "All quest givers, objectives and turn-ins on the map. Keine Zeit Leveling Guide builds the route from that."
T["Bist du in einer Gruppe, teilt Keine Zeit Leveling Guide passende Quests von selbst und zeigt im Mini Fenster, wie weit die anderen sind."] = "When you're in a group, Keine Zeit Leveling Guide shares fitting quests by itself and shows in the mini window how far the others are."
T["Keine Zeit Leveling Guide rechnet dir die schnellste Leveling Route und führt dich mit Pfeil, Karte und Mini HUD."] = "Keine Zeit Leveling Guide calculates the fastest leveling route for you and guides you with the arrow, map and mini HUD."
T["Keine Zeit Leveling Guide sucht jetzt Quests mit besserer Belohnung als deine Ausrüstung. So wirst du unterwegs besser, ohne Händler oder Auktionshaus."] = "Keine Zeit Leveling Guide now looks for quests with rewards better than your gear. So you upgrade along the way, no vendor or auction house needed."
T["Keine Zeit Leveling Guide zeigt dir immer, was als Nächstes kommt und wohin du läufst. Du musst nichts planen. Ein paar kurze Fragen, dann geht es los."] = "Keine Zeit Leveling Guide always shows you what's next and where to go. No planning needed. A few quick questions, then off you go."
T["Das ist kein Keine Zeit Leveling Guide Text"] = "This is not a Keine Zeit Leveling Guide text"
T["Fahrplan|r  bei der Einrichtung rechnet Keine Zeit Leveling Guide im Hintergrund einen Fahrplan bis Level 60 (Startgebiet bis Level 6, Klassenquests und Lehrer fest drin). Zonenwechsel kosten extra, darum macht die Route erst die Zone fertig."] = "Level plan|r  during setup Keine Zeit Leveling Guide calculates a level plan up to level 60 in the background (starting zone up to level 6, class quests and trainers built in). Changing zones costs extra, so the route finishes the zone first."
T["Keine Zeit Leveling Guide einrichten"] = "Keine Zeit Leveling Guide setup"
T["Keine Zeit Leveling Guide: Karte umschalten. Jetzt neu laden?"] = "Keine Zeit Leveling Guide: switch map. Reload now?"
T["Haben andere in der Gruppe Keine Zeit Leveling Guide, steht im HUD ihr Stand bei gemeinsamen Quests, zum Beispiel "] = "If others in your group have Keine Zeit Leveling Guide, the HUD shows their progress on shared quests, for example "
T["In %s kennt Keine Zeit Leveling Guide noch keine Angelstelle: dort eine Stelle am Wasser suchen."] = "Keine Zeit Leveling Guide doesn't know a fishing spot in %s yet: find a spot by the water there."
T["Keine Rezepte bekannt. Öffne einmal dein Berufsfenster, dann lernt Keine Zeit Leveling Guide deine Rezepte."] = "No recipes known. Open your profession window once and Keine Zeit Leveling Guide learns your recipes."
T["Kennt Kräuter, Erz und Fischschwärme. Ohne nimmt Keine Zeit Leveling Guide eigene Listen und lernt beim Farmen dazu, kennt am Anfang aber weniger."] = "Knows herbs, ore and fish schools. Without it Keine Zeit Leveling Guide uses its own lists and learns while you farm, but knows fewer spots at first."
T["Klick visiert ihn an. Eine Taste gibt es unter Tastaturbelegung, Keine Zeit Leveling Guide."] = "Click to target. Set a key under Key Bindings, Keine Zeit Leveling Guide."
T["Kräuter, Erz, Leder, Stoff, Fleisch und Fische farmen. Du wählst, was du brauchst, Keine Zeit Leveling Guide sucht die Gebiete und plant eine Runde. Mehrere Berufe gehen zusammen."] = "Farm herbs, ore, leather, cloth, meat and fish. You pick what you need, Keine Zeit Leveling Guide finds the areas and plans a loop. Several professions work together."
T["Linksklick: Keine Zeit Leveling Guide Seite"] = "Left-click: Keine Zeit Leveling Guide page"
T["Look auf %s wechseln?\n\nAlle Fenster von Keine Zeit Leveling Guide bekommen andere Farben, Rahmen und Knöpfe. Dafür lädt die Oberfläche neu, das dauert ein paar Sekunden.\n\nAbbrechen: es bleibt wie es ist."] = "Switch look to %s?\n\nAll Keine Zeit Leveling Guide windows get different colors, borders and buttons. The UI reloads for this, which takes a few seconds.\n\nCancel: everything stays as it is."
T["Mit Keine Zeit Leveling Guide wachsen"] = "Grow with Keine Zeit Leveling Guide"
T["Mit echten AH Preisen weiss Keine Zeit Leveling Guide, welche Beute sich lohnt und was du verkaufen sollst."] = "With real AH prices Keine Zeit Leveling Guide knows which loot is worth it and what you should sell."
T["Neu bei Keine Zeit Leveling Guide"] = "New to Keine Zeit Leveling Guide"
T["Nichts angehakt: Keine Zeit Leveling Guide sucht die besten Gebiete selber."] = "Nothing checked: Keine Zeit Leveling Guide finds the best areas by itself."
T["Pfeil gesperrt. Klicks gehen durch ihn durch. Rechtsklick auf den Keine Zeit Leveling Guide Text gibt ihn wieder frei."] = "Arrow locked. Clicks go through it. Right-click the Keine Zeit Leveling Guide text to unlock it again."
T["QuestieDB|r müssen an sein. Fehlt etwas, sagt dir Keine Zeit Leveling Guide beim Einloggen Bescheid."] = "QuestieDB|r must be enabled. If something is missing, Keine Zeit Leveling Guide tells you when you log in."
T["Quests werden automatisch mit Mitspielern geteilt, die Keine Zeit Leveling Guide haben, die Quest noch nicht haben und in Reichweite sind."] = "Quests are shared automatically with group members who have Keine Zeit Leveling Guide, don't have the quest yet and are in range."
T["Quests werden automatisch mit der Gruppe geteilt (nur Mitspieler mit Keine Zeit Leveling Guide, in Reichweite)"] = "Quests are shared with the group automatically (only players with Keine Zeit Leveling Guide, in range)"
T["Rechts an der Karte sind die Knöpfe von Keine Zeit Leveling Guide. Klick auf das Logo klappt die Leiste zu und wieder auf."] = "The Keine Zeit Leveling Guide buttons are on the right side of the map. Clicking the logo collapses and expands the bar."
T["Rechts unten das Keine Zeit Leveling Guide Logo. Dort ist das ganze Menü."] = "The Keine Zeit Leveling Guide logo at the bottom right. The whole menu is there."
T["Schwärme kennt Keine Zeit Leveling Guide nur mit GatherMate2."] = "Keine Zeit Leveling Guide only knows schools with GatherMate2."
T["Taschen fast voll. Nach dieser Route plant Keine Zeit Leveling Guide wieder Händler ein."] = "Bags almost full. After this route Keine Zeit Leveling Guide plans vendor stops again."
T["Tipp: Alle Zeiten werden genauer, je länger du spielst. Keine Zeit Leveling Guide misst dein Lauftempo, Reittier, Kampfzeit pro Mob Level und Pausen.|r"] = "Tip: All times get more accurate the longer you play. Keine Zeit Leveling Guide measures your running speed, mount, combat time per mob level and breaks.|r"
T["Wege um Berge|r  Das Spiel hat keine Geländedaten, darum lernt Keine Zeit Leveling Guide, wo man laufen kann: überall, wo du schon warst,"] = "Paths around mountains|r  The game has no terrain data, so Keine Zeit Leveling Guide learns where you can walk: everywhere you have already been,"
T["Keine Zeit Leveling Guide Leiste"] = "Keine Zeit Leveling Guide bar"
T["Keine Zeit Leveling Guide pausieren"] = "Pause Keine Zeit Leveling Guide"
T["Keine Zeit Leveling Guide pausiert"] = "Keine Zeit Leveling Guide paused"
T["Keine Zeit Leveling Guide weitermachen"] = "Resume Keine Zeit Leveling Guide"
T["Keine Zeit Leveling Guide: Quests für %s: %s. Am Eingang wird geteilt."] = "Keine Zeit Leveling Guide: quests for %s: %s. We share at the entrance."
T["Keine Zeit Leveling Guide: besser aus einer Quest"] = "Keine Zeit Leveling Guide: better item from a quest"
T["Keine Rezepte bekannt. Ohne AtlasLoot kennt Keine Zeit Leveling Guide nur Rezepte, die du gelernt hast: öffne einmal dein Berufsfenster (zb Kochen), dann merkt es sich die Rezepte."] = "No recipes known. Without AtlasLoot, Keine Zeit Leveling Guide only knows recipes you learned: open your profession window once (e.g. Cooking), then it remembers them."
T["Willkommen bei Keine Zeit Leveling Guide!|r"] = "Welcome to Keine Zeit Leveling Guide!|r"
T["Willkommen beim Keine Zeit Leveling Guide"] = "Welcome to Keine Zeit Leveling Guide"
T["automatisch, Keine Zeit Leveling Guide sucht die besten"] = "automatic, Keine Zeit Leveling Guide picks the best"
T["die Stellen von Kräutern, Erz und Fischschwärmen von GatherMate2. Keine Zeit Leveling Guide nimmt dann die eingebauten Gebietslisten und lernt selber"] = "the herb, ore and fishing pool spots from GatherMate2. Keine Zeit Leveling Guide then uses its built-in zone lists and learns on its own"
T["|cff7fd1b9Keine Zeit Leveling Guide:|r beim Händler verkaufen"] = "|cff7fd1b9Keine Zeit Leveling Guide:|r sell to a vendor"
T["|cff7fd1b9Keine Zeit Leveling Guide:|r lieber ins AH, ca %s"] = "|cff7fd1b9Keine Zeit Leveling Guide:|r better on the AH, about %s"
T["|cff9d9d9dEingesammelt erkennt Keine Zeit Leveling Guide selbst: am Fundort aufgehoben oder in deinen Taschen. Bücher Route führt zu allen offenen Büchern ausser denen in Dungeons.|r"] = "|cff9d9d9dKeine Zeit Leveling Guide detects collected books by itself: picked up at the spot or in your bags. The books route leads to all open books except those in dungeons.|r"
T["|cffff5050Keine Zeit Leveling Guide: nicht verkaufen, "] = "|cffff5050Keine Zeit Leveling Guide: don't sell, "
T["Wege teilen|r  Wo du gelaufen bist, geht frühestens nach 45 Minuten an andere Spieler mit Keine Zeit Leveling Guide, ihre Wege kommen zu dir."] = "Share paths|r  Where you walked goes to other players with Keine Zeit Leveling Guide after 45 minutes at the earliest, their paths come to you."
T["Wege teilen: Auf diesem Server kann Keine Zeit Leveling Guide den versteckten Kanal nicht nutzen. Wege gehen jetzt nur über Gilde und Gruppe."] = "Share paths: on this server Keine Zeit Leveling Guide cannot use the hidden channel. Paths now go through guild and group only."
T["   Kommst du ihnen nahe, warnt Keine Zeit Leveling Guide. Allein schickt dich die Route nie in ein Elite Lager, und ein einzelner"] = "   When you come close, Keine Zeit Leveling Guide warns you. Solo, the route never sends you into an elite camp, and a single"
T["Ja: die Route rechnet langsamer, dafür ruckelt nichts. Bei Ruckeln bremst Keine Zeit Leveling Guide auch von selbst."] = "Yes: the route calculates more slowly, but nothing stutters. If it stutters, Keine Zeit Leveling Guide also slows down by itself."
T["|cffff9030Achtung:|r Für Level %d findet Keine Zeit Leveling Guide keine Quests (Volk %s, ID %s). Bitte über \"Fehler melden\" kurz Bescheid geben, die Gründe stehen im Log."] = "|cffff9030Note:|r Keine Zeit Leveling Guide finds no quests for level %d (race %s, ID %s). Please report it via \"Report bug\", the reasons are in the log."
T[" müssen an sein. Fehlt etwas, sagt dir Keine Zeit Leveling Guide beim Einloggen Bescheid."] = " must be enabled. If something is missing, Keine Zeit Leveling Guide tells you when you log in."
T["Das Spiel hat keine Geländedaten. Darum lernt Keine Zeit Leveling Guide, wo man laufen kann: wo du schon warst, wo Mobs und NPCs stehen und welche Übergänge zwischen Zonen du benutzt hast. Pfeil und Karte nehmen dann den bekannten Weg statt quer über den Berg."] = "The game has no terrain data. So Keine Zeit Leveling Guide learns where you can walk: where you've been, where mobs and NPCs stand and which zone crossings you've used. The arrow and map then take the known path instead of going straight over the mountain."
T["  Wo du gelaufen bist, geht frühestens nach 45 Minuten an andere Spieler mit Keine Zeit Leveling Guide. Eine Stelle gilt erst als frei, wenn viele Spieler an verschiedenen Tagen dort laufen. Einen Berg setzen andere nie. "] = "  Where you've walked is sent to other players with Keine Zeit Leveling Guide after 45 minutes at the earliest. A spot only counts as clear once many players have walked there on different days. Others can never set a mountain. "
T["Keine Zeit Leveling Guide rechnet eine "] = "Keine Zeit Leveling Guide calculates a "
T["Haben andere in der Gruppe Keine Zeit Leveling Guide, siehst du im Mini Fenster ihren Stand bei gemeinsamen Quests. An einer Abgabe steht, auf wen du noch warten musst."] = "If others in your group have Keine Zeit Leveling Guide, the mini window shows their progress on shared quests. At a turn in it shows who you still need to wait for."
T["Keine Zeit Leveling Guide kennt noch keinen Weg dort. Lauf einmal den richtigen Weg, dann lernt er ihn. Oder setze mit Alt+Klick auf der Karte eine Gefahr."] = "Keine Zeit Leveling Guide doesn't know a path there yet. Walk the right way once and it learns it. Or set a danger with Alt+click on the map."
T["Am Anfang sind es Schätzwerte. Je länger du spielst, desto genauer, weil Keine Zeit Leveling Guide dein Lauftempo, dein Reittier, die Kampfzeit pro Mob und deine Pausen misst."] = "At first they're estimates. The longer you play, the more accurate they get, because Keine Zeit Leveling Guide measures your walking speed, your mount, combat time per mob and your breaks."
T["Unten der Reiter Keine Zeit Leveling Guide. Oder /klg für das grosse Fenster."] = "The Keine Zeit Leveling Guide tab at the bottom. Or /klg for the main window."
T["Kräuter, Erz, Leder, Stoff, Fleisch und Fische farmen. Du wählst, was du brauchst, Keine Zeit Leveling Guide plant die Runde, auch für mehrere Berufe."] = "Farm herbs, ore, leather, cloth, meat and fish. Pick what you need, Keine Zeit Leveling Guide plans the loop, even for several professions."
T["|cffffd100%s ist auch an.|r Das ist ok. Setzt es eigene Wegpunkte, siehst du dort einen zweiten Pfeil. Der Pfeil vom Keine Zeit Leveling Guide zeigt immer auf die Route."] = "|cffffd100%s is also enabled.|r That's fine. If it sets its own waypoints, you'll see a second arrow there. The Keine Zeit Leveling Guide arrow always points along the route."
T["|cffffd100%s ist auch an.|r Zwei Leveling Guides gleichzeitig zeigen zwei Pfeile und verschiedene Routen. Tipp: einen davon ausschalten. Keine Zeit Leveling Guide läuft trotzdem normal weiter."] = "|cffffd100%s is also enabled.|r Two leveling guides at once show two arrows and different routes. Tip: turn one of them off. Keine Zeit Leveling Guide keeps working normally."
T["Das geht, aber zwei Leveling Guides zeigen zwei Pfeile und verschiedene Routen. Keine Zeit Leveling Guide sagt einmal Bescheid und läuft normal weiter. Am einfachsten ist ein Guide zur Zeit."] = "That works, but two leveling guides show two arrows and different routes. Keine Zeit Leveling Guide tells you once and keeps working. One guide at a time is easiest."
T["Rechts an der Karte sind die Knöpfe von Keine Zeit Leveling Guide. Das Logo oder Plus und Minus klappt die Leiste auf und zu."] = "The Keine Zeit Leveling Guide buttons are on the right of the map. The logo or plus and minus folds the bar in and out."
T["Export braucht Keine Zeit Leveling Guide 17.9 oder neuer."] = "Export needs Keine Zeit Leveling Guide 17.9 or newer."
T["|cffffd100%s ist auch an.|r Zusammen mit Auto Quest vom Keine Zeit Leveling Guide klicken beide, und das schnellere wählt die Belohnung. Tipp: nur eins davon an lassen."] = "|cffffd100%s is also enabled.|r Together with Auto Quest from Keine Zeit Leveling Guide both click, and the faster one picks the reward. Tip: keep only one of them on."
T["Die Gelände Karte (im Addon, Ordner Karte) kennt Berge, Wasser, Klippen, Wege und die Übergänge zwischen den Zonen. Damit rechnet die Route die echten Laufwege, und der Pfeil führt Stück für Stück um das Gelände, auch über mehrere Zonen. Dazu lernt Keine Zeit Leveling Guide, wo du schon gelaufen bist: dort ist nie ein Berg. "] = "The terrain map (inside the addon, folder Karte) knows mountains, water, cliffs, paths and the crossings between zones. With it the route calculates the real walking paths, and the arrow leads step by step around the terrain, also across several zones. On top Keine Zeit Leveling Guide learns where you have walked: there is never a mountain there. "
T[")? Ohne sie kennt Keine Zeit Leveling Guide nur die Wege, die du gelaufen bist. Lauf einmal den richtigen Weg, dann lernt er ihn. Oder setze mit Alt+Klick auf der Karte eine Gefahr."] = ")? Without it Keine Zeit Leveling Guide only knows the paths you walked. Walk the right path once, then it learns it. Or set a danger with Alt+Click on the map."
T["Das ist das grosse Fenster. Später öffnest du es mit der Taste C (Reiter Keine Zeit Leveling Guide im Charakterfenster), mit /klg oder im Mini Fenster unter Menü, Grosses Fenster."] = "This is the big window. Later you open it with the C key (Keine Zeit Leveling Guide tab in the character window), with /klg or in the mini window under Menu, Big window."
T["Alle Texte von Keine Zeit Leveling Guide grösser oder kleiner (80 bis 150 %), zb wenn man schlecht sieht. Das grosse Fenster kannst du zusätzlich unten rechts am Griff grösser ziehen."] = "All Keine Zeit Leveling Guide texts bigger or smaller (80 to 150 %), for example if you see poorly. You can also drag the big window larger at the grip in the bottom right corner."
T["Quest Hubs: %d Quests gleich beim ersten Besuch angenommen"] = "Quest hubs: %d quests picked up on the first visit"
-- 20.3j
T["Wie viele nächste Schritte das Mini Fenster zeigt: 1, 3, 5, 8, dann wieder 1. Gleich wie unter Einstellungen."] = "How many next steps the mini window shows: 1, 3, 5, 8, then back to 1. Same as in the settings."
T["Schritte: %d"] = "Steps: %d"
T["Route wird berechnet: %d %%, jetzt bei Level %d"] = "Calculating route: %d %%, now at level %d"
T["Level 60 erreicht: es gibt keinen Plan bis 60 mehr. Restliche Quests: im Mini Fenster Menü, Ziel wählen (Ausrüstung, Ruf, Dungeons, Gold) oder Tempo Alles."] = "Level 60 reached: there is no plan to 60 anymore. Remaining quests: mini window menu, Choose goal (gear, reputation, dungeons, gold) or pace Everything."
T["Level 60 erreicht, kein Plan bis 60 mehr."] = "Level 60 reached, no plan to 60 anymore."
T["Es wird geloggt. Fehler oder Ideen im Kasten Test Notiz eintragen. Aus mit /klg log stop."] = "Logging is on. Enter bugs or ideas in the Test note box. Turn off with /klg log stop."
T["Wie schalte ich das Log ein und aus?|r"] = "How do I turn the log on and off?|r"
T["/klg log start schaltet das Test Log ein und öffnet den Kasten Test Notiz (Fehler melden, Verbesserung). Solange es läuft, wird mitgeschrieben. /klg log stop schaltet es aus, was drin ist, bleibt. Es gibt eine Log Datei pro Konto (für alle Charaktere und Server zusammen), sie heisst KeineZeitLevelingGuide_Log.lua und liegt in WTF\\Account\\<Konto>\\SavedVariables. Das Spiel schreibt sie erst beim Ausloggen oder nach /reload. Schick diese Datei mit einer kurzen Notiz, was passiert ist. Für das Log braucht es das Addon KeineZeitLevelingGuide_Log (im AddOns Ordner, im Charakter Menü bei AddOns an)."] = "/klg log start turns the test log on and opens the Test note box (report bug, suggestion). While it runs, everything is recorded. /klg log stop turns it off, what is in it stays. There is one log file per account (all characters and realms together), called KeineZeitLevelingGuide_Log.lua in WTF\\Account\\<account>\\SavedVariables. The game writes it only on logout or after /reload. Send this file with a short note about what happened. The log needs the addon KeineZeitLevelingGuide_Log (in the AddOns folder, enabled in the character menu under AddOns)."
T["%s, dann Flug nach %s"] = "%s, then fly to %s"
T["Angel Skill %d, die gewählten Fische gibt es erst ab Skill %d. Wähle die Zone selbst, dann geht es trotzdem."] = "Fishing skill %d, the chosen fish start at skill %d. Pick the zone yourself and it works anyway."
T["Für die gewählten Fische ist keine Zone bekannt."] = "No zone is known for the chosen fish."
T["Hinweis: in %s braucht es Angel Skill %d, du hast %d. Du fängst dort vielleicht noch wenig."] = "Note: %s needs fishing skill %d, you have %d. You may catch little there for now."
T["Nichts angehakt: alle Ausrüstung Quests sind jetzt gewählt. Links kannst du einzelne wieder abwählen."] = "Nothing checked: all gear quests are selected now. You can uncheck single ones on the left."
T["Ausrüstung Route: %d Quests mit Vorquests, wird berechnet. Danach geht die Leveling Route weiter, wo du warst."] = "Gear route: %d quests with prequests, calculating. Afterwards the leveling route continues where you were."
T["Ausrüstung Route: keine Route gefunden (Quests nicht erreichbar oder Level zu tief)."] = "Gear route: no route found (quests not reachable or level too low)."
T["weiter: Flug nach %s"] = "next: fly to %s"
-- 20.3k
T["Level 60 erreicht: die Route plant jetzt alle restlichen Quests (wie Tempo Alles). Dazu im Mini Fenster Menü unter Ziel wählen: Ausrüstung, Ruf, Dungeons, Gold."] = "Level 60 reached: the route now plans all remaining quests (like pace Everything). Also in the mini window menu under Choose goal: gear, reputation, dungeons, gold."
T["%s, %d von %d hier"] = "%s, %d of %d here"
T[". Eigene Route mit Vorquests wird berechnet, danach geht die Leveling Route weiter."] = ". Own route with prequests is being calculated, afterwards the leveling route continues."
T["Teleport"] = "Teleport"
T["hier"] = "here"
-- 20.3l
T["Alle übrigen Quests"] = "All remaining quests"
T["Du bist auf Max Level: rechnet eine Route mit allen Quests, die du noch machen kannst."] = "You are at max level: calculates a route with all quests you can still do."
-- 20.3m
T["Der Ordner %s ist auch noch eingeschaltet. Bitte nur einen laufen lassen: im Charakter Menü bei AddOns den alten ausschalten."] = "The folder %s is also still enabled. Please run only one: turn off the old one under AddOns in the character menu."
T["Gefahren auf der Karte?"] = "Dangers on the map?"
T["Von dir gesetzte Gefahren (Alt+Klick), starke Mobs und Elite für dein Level. Gelernte Sturz Stellen nutzt die Route, zeigt sie aber nicht."] = "Dangers you set (Alt+click), strong mobs and elites for your level. Learned fall spots are used by the route but not shown."
-- 20.3o (Da Pruefung Nr 14)
T["\n|cff9d9d9dRunde %d, Punkt %d von %d|r"] = "\n|cff9d9d9dRound %d, point %d of %d|r"
T["Max Level: keine Leveling Route mehr. Für alle übrigen Quests im Mini Fenster Menü auf \"Alle übrigen Quests\"."] = "Max level: no leveling route anymore. For all remaining quests use \"All remaining quests\" in the mini window menu."
T["Teleport nach "] = "Teleport to "
-- 20.3q (Na NaviFlug 46ea1ff6)
T["Flug nach %s startet gleich. Abbrechen: Shift halten oder die Flugkarte schliessen"] = "Flight to %s starts soon. To cancel: hold Shift or close the flight map"
-- 20.3r
T["Item nur von Elite, Dungeon oder Raid"] = "Item only from elites, dungeons or raids"
T["Zufall Drop, kommt auf Max Level"] = "Random drop, comes at max level"
-- 20.4a3 (Na Arrow 6e41dd23, Stadt Tore)
T["\n|cff9d9d9dStadt: erst zum Tor|r"] = "\n|cff9d9d9dCity: to the gate first|r"
T["%d von %d Stufen erreicht"] = "%d of %d stages reached"
-- 20.4a4 (K 21:00 Mein Weg, K 21:02 Hilfe Log Abschnitt)
T["Log und Fehler melden"] = "Log and bug reports"
T["  Log für Fehler Meldungen, mehr dazu im Abschnitt Log und Fehler melden."] = "  log for bug reports, more in the section Log and bug reports."
T["Alles dazu steht im Abschnitt Log und Fehler melden."] = "Everything about it is in the section Log and bug reports."
T["Wofür ist das Log?|r"] = "What is the log for?|r"
T["Läuft etwas falsch (Pfeil, Route, Fenster), schreibt das Log mit, was das Addon gerade tut. Mit der Log Datei kann der Fehler gefunden werden. Es läuft nur, wenn du es einschaltest."] = "If something goes wrong (arrow, route, window), the log records what the addon is doing. The log file helps to find the bug. It only runs when you turn it on."
T["Was brauche ich dafür?|r"] = "What do I need?|r"
T["Das Addon %s muss im AddOns Ordner sein und im Charakter Menü bei AddOns an. Ohne es gibt es kein Log, der Rest läuft normal."] = "The addon %s must be in the AddOns folder and enabled in the AddOns list at character select. Without it there is no log, everything else works normally."
T["/klg log start"] = "/klg log start"
T["/klg log stop"] = "/klg log stop"
T["  schaltet das Log ein und öffnet den Kasten Test Notiz. Solange es läuft, wird mitgeschrieben."] = "  turns the log on and opens the Test note box. While it runs, everything is recorded."
T["  schaltet es aus. Was schon drin ist, bleibt."] = "  turns it off. What is already in it stays."
T["Wie sage ich, was passiert ist?|r"] = "How do I say what happened?|r"
T["Im Kasten Test Notiz kurz eintragen, was komisch war (Fehler oder Idee). Oder im Chat:"] = "Write in the Test note box what was odd (bug or idea). Or in chat:"
T["  schreibt deine Notiz mit dem Stand vom Addon ins Log, zum Beispiel: hier lief er in den Berg."] = "  writes your note with the addon state into the log, for example: here it ran into the mountain."
T["Wo liegt die Datei und welche schicke ich?|r"] = "Where is the file and which one do I send?|r"
T["Eine Log Datei pro Konto (alle Charaktere und Server zusammen): WTF\\Account\\<Konto>\\SavedVariables\\%s.lua. Schick genau diese Datei mit deiner Notiz. Nicht %s.lua, das sind nur deine Einstellungen."] = "One log file per account (all characters and realms together): WTF\\Account\\<account>\\SavedVariables\\%s.lua. Send exactly this file with your note. Not %s.lua, that is only your settings."
T["Wann ist alles drin?|r"] = "When is everything in it?|r"
T["Das Spiel schreibt die Datei erst beim Ausloggen oder nach /reload. Also erst ausloggen oder /reload, dann die Datei schicken."] = "The game writes the file only on logout or after /reload. So log out or /reload first, then send the file."
T["Für das Test Log braucht es das Addon %s (eigener Ordner in AddOns, im Charakter Menü bei AddOns einschalten)."] = "The test log needs the addon %s (its own folder in AddOns, enable it in the AddOns list at character select)."
T["Zum Schicken: %s.lua aus WTF, Account, dein Konto, SavedVariables. Nicht %s.lua, das sind nur die Einstellungen."] = "To send it: %s.lua from WTF, Account, your account, SavedVariables. Not %s.lua, that is only the settings."
T["Test Log %s, %d Zeilen, Sitzung %s. Gespeichert wird beim Ausloggen oder /reload in WTF, SavedVariables, %s.lua (verschlüsselt)."] = "Test log %s, %d lines, session %s. Saved on logout or /reload in WTF, SavedVariables, %s.lua (encrypted)."
T["Objekt (Buch), nicht anvisierbar: in der Welt mit Rechtsklick benutzen"] = "Object (book), cannot be targeted: right click it in the world"
