T["Dein Charakter läuft den ganzen Weg nochmal ab, in der Ausrüstung von damals (jedes Level)."] = "Your character walks the whole path again, in the gear you wore back then (every level)."
T["Dein Charakter läuft als kleine Figur den Weg entlang bis zu deinem Level, mit der Ausrüstung, die du trägst. Bei jedem Level merkt sich das Addon, was du anhast, und die Figur bleibt bei einem Upgrade kurz stehen. "] = "Your character walks the path as a small figure up to your level, wearing your gear. The addon remembers your gear at every level, and the figure stops briefly at each upgrade. "
